function notifyPriceWatchers(product,oldPrice,newPrice){if(!product||Number(oldPrice)===Number(newPrice))return;const all=readPriceWatchers(),drop=Number(newPrice)<Number(oldPrice);let sent=0;Object.entries(all).forEach(([phone,ids])=>{if((ids||[]).map(String).includes(String(product.id))){pushPersonalNotification(phone,{title:`${drop?'🎉 کاهش':'🔔 تغییر'} قیمت ${product.name}`,body:`قیمت ${product.name} تغییر کرد: ${money(oldPrice)} تومان ← ${money(newPrice)} تومان. ${drop?'فرصت خرید با قیمت جدید را بررسی کن.':'قیمت جدید را پیش از خرید بررسی کن.'}`,type:drop?"sale":"info",source:"price-change",productId:product.id,oldPrice:Number(oldPrice),newPrice:Number(newPrice)});sent++;}});let botData={};try{botData=JSON.parse(localStorage.getItem("novin_bot_data")||"{}")}catch{}const botWatchers=Array.isArray(botData.priceWatchers)?botData.priceWatchers:[];botWatchers.filter(w=>String(w.productId)===String(product.id)).forEach(w=>{const actor={phone:w.phone,name:w.name||"ربات آزمایشی",time:Date.now()};recordBotProductAction("دریافت اعلان تغییر قیمت",product.id,{oldPrice:Number(oldPrice),newPrice:Number(newPrice),direction:drop?"کاهش":"افزایش"},actor);});return sent;}
