function paidOrderCount(phone){return orders.filter(o=>normalizePhone(o.customer?.phone)===normalizePhone(phone)&&["paid","processing","sent","delivered","completed"].includes(o.status)&&! ["wallet_topup","plus_subscription"].includes(o.type)).reduce((total,o)=>total+(Array.isArray(o.items)?o.items.reduce((n,i)=>n+Math.max(1,Number(i.qty||i.quantity)||1),0):1),0)}
