 const mine=orders.filter(o=>o.customer.phone===currentUser.phone).slice().reverse(), balance=walletBalance(currentUser.phone);
 const tabBtn=(key,label)=>`<button class="profile-tab ${tab===key?'active':''}" data-profile-tab="${key}">${label}</button>`;
 let content="";
