 if(tab==="transactions"){const tx=walletTransactions.filter(t=>normalizePhone(t.phone)===normalizePhone(currentUser.phone)).slice().reverse();content=`<div class="profile-section-head"><h3>تراکنش‌های کیف پول</h3><span>${digits(tx.length)} تراکنش</span></div>${tx.map(t=>`<div class="customer-row"><div class="mini-info"><b>${escapeHtml(t.note||'تراکنش کیف پول')}</b><small>${new Date(t.time||Date.now()).toLocaleString('fa-IR')} · ${escapeHtml(t.paymentReference||'بدون کد پیگیری')}</small></div><strong>${t.type==='credit'?'+':'−'} ${money(t.amount||0)}</strong></div>`).join('')||'<p class="muted">هنوز تراکنشی ثبت نشده است.</p>'}`;}
 if(tab==="gemSecurity")content=`<div class="panel-card"><h3>امنیت حساب</h3><p>شماره حساب: ${escapeHtml(currentUser.phone)}</p><p class="muted">رمز عبور و کدهای یک‌بارمصرف در پنل مدیریت نمایش داده نمی‌شوند. برای تغییر رمز از خروج و گزینه بازیابی رمز در صفحه ورود استفاده کن.</p><button class="outline" id="gemSecurityLogout" data-account-logout>خروج از حساب</button></div>`;
 if(tab==="gemGuide")content=`<div class="panel-card"><h3>راهنمای خرید جم</h3><ol><li>بسته جم را انتخاب کن.</li><li>Player ID را با دقت وارد کن.</li><li>روش پرداخت آزمایشی را انتخاب کن.</li><li>شماره سفارش را از بخش سفارش‌ها برای پیگیری نگه‌دار.</li></ol><p class="muted">این فروشگاه آزمایشی است و جم واقعی به حساب بازی ارسال نمی‌کند.</p></div>`;
