function cartQty(){return cart.reduce((s,x)=>s+x.qty,0)}
function subtotal(){return cart.reduce((s,x)=>s+((Number(x.unitPrice)||productById(x.id)?.price||0)+Number(x.insurancePrice||0))*x.qty,0)}
function discountValue(){if(!appliedCoupon)return 0;const global=discounts.find(d=>d.code.toUpperCase()===appliedCoupon.toUpperCase()&&d.active);const personal=findPersonalCoupon(appliedCoupon,currentUser?.phone);const c=personal||global;return c?Math.round(subtotal()*c.percent/100):0}
function hasActiveNovinPlus(phone=currentUser?.phone){
 if(!phone)return false;
 const normalized=normalizePhone(phone);
 return plusSubscriptions.some(x=>normalizePhone(x.phone)===normalized&&x.status==="active"&&(!x.expiresAt||Number(x.expiresAt)>Date.now()));
}
function shipping(){
 const chosen=shippingCompanies.find(x=>x.active&&x.id===selectedShippingCompany);
 if(subtotal()===0||subtotal()>=5000000||hasActiveNovinPlus())return 0;
 return chosen?.fee??150000;
}
function total(){return Math.max(0,subtotal()+shipping()-discountValue())}
function productCardMarkup(p,compact=false){
 const ratingRows=reviews.filter(r=>r.productId===p.id),rating=ratingRows.length?ratingRows.reduce((n,r)=>n+r.rating,0)/ratingRows.length:Number(p.rating||4.5);
 const cardImages=[...new Set([...(Array.isArray(p.images)?p.images:[]),p.image].filter(x=>typeof x==="string"&&x.trim()))];
 return `<article class="product-card ${compact?'category-product-card':''}"><div class="product-visual" data-card-images="${escapeHtml(JSON.stringify(cardImages))}">${p.image?`<img class="product-real-photo product-card-slideshow" src="${escapeHtml(p.image)}" alt="${escapeHtml(p.name)}" loading="lazy" onerror="this.dataset.broken='1'">`:`<div class="product-emoji-pair" aria-label="آیکون‌های محصول"><span class="product-emoji-main">${escapeHtml(p.emoji||"📦")}</span><span class="product-emoji-secondary">${escapeHtml(p.icon2||({"موبایل":"🛡️","هدفون":"🎵","شارژر":"⚡","لوازم جانبی":"🧩","ساعت هوشمند":"❤️","ذخیره‌سازی":"📁","گیمینگ":"🕹️","اسپیکر":"🎶","کامپیوتر و شبکه":"🌐","عکاسی و تولید محتوا":"💡"}[p.category]||"✨"))}</span></div>`}${p.tag?`<span class="product-badge">${escapeHtml(p.tag)}</span>`:""}<div class="product-card-icon-actions"><button class="wish ${wishlist.includes(p.id)?"active":""}" data-wish="${p.id}" title="علاقه‌مندی" aria-label="افزودن به علاقه‌مندی‌ها">${wishlist.includes(p.id)?"♥":"♡"}</button><button class="product-quick-view" data-product-details="${p.id}" title="مشاهده سریع" aria-label="مشاهده سریع محصول">⌕</button></div></div><div class="product-info"><span class="product-category">${escapeHtml(p.category)}</span><h3>${escapeHtml(p.name)}</h3><p class="product-card-description">${escapeHtml(p.description||"جزئیات محصول را مشاهده کنید.")}</p><div class="rating">★ ${rating.toFixed(1)} <span>· ${digits(ratingRows.length)} نظر · ${p.stock>0?"موجود":"ناموجود"}</span></div><div class="product-bottom"><div><div class="price">${money(p.price)}</div>${p.oldPrice>p.price?`<span class="old-price">${money(p.oldPrice)}</span>`:""}</div><button class="add-cart" data-add="${p.id}" ${p.stock<=0?"disabled":""} aria-label="افزودن به سبد">+</button></div><div class="product-card-links"><button class="product-details-btn" data-product-details="${p.id}">جزئیات و مشخصات ←</button><button class="review-link" data-review-product="${p.id}">ثبت نظر</button></div></div></article>`;
}
function openCategoryView(category){activeCategory=category;$$('.category[data-category]').forEach(x=>x.classList.toggle('active',x.dataset.category===category));renderProducts();requestAnimationFrame(()=>$('#products')?.scrollIntoView({behavior:'smooth',block:'start'}));}
function renderProducts(){
 const published=products.filter(p=>p.published!==false),stockOnly=$('#stockFilter')?.value==='in';
 let list=published.filter(p=>(activeCategory==='همه'||p.category===activeCategory)&&(`${p.name} ${p.category} ${p.description||''} ${p.brand||''} ${p.tags||''}`).toLowerCase().includes(searchTerm.toLowerCase())&&(!stockOnly||p.stock>0));
 const sort=$('#sortSelect')?.value||'featured';
 const sorter=(a,b)=>sort==='price-low'?a.price-b.price:sort==='price-high'?b.price-a.price:sort==='name'?a.name.localeCompare(b.name,'fa'):sort==='rating'?Number(b.rating||0)-Number(a.rating||0):Number(Boolean(b.featured))-Number(Boolean(a.featured))||Number(b.rating||0)-Number(a.rating||0);
 list.sort(sorter);
 const grid=$('#productGrid');
 $('#products').querySelector('h2').textContent=activeCategory==='همه'?'محصولات منتخب':activeCategory;
 $('#products').querySelector('p').textContent=activeCategory==='همه'?'محصول دلخواهت را پیدا کن.':'تمام محصولات این دسته‌بندی را بررسی کن.';
 $('#filterLabel').textContent=`${activeCategory==='همه'?'همه محصولات':activeCategory} · ${digits(list.length)} محصول`;
 grid.className='product-grid';grid.innerHTML=list.length?list.map(p=>productCardMarkup(p)).join(''):`<div class="empty-state" style="grid-column:1/-1"><b>⌕</b>محصولی با این مشخصات پیدا نشد.</div>`;
 renderFlashSale();renderBestSellers();
}

function renderCart(){
 $("#cartCount").textContent=digits(cartQty());$("#drawerCount").textContent=`(${digits(cartQty())})`;
 $("#cartItems").innerHTML=cart.length?`<div class="cart-compare-toolbar"><div><b>مقایسه کالاهای سبد خرید</b><small>تا ۴ کالا را از نظر قیمت و مشخصات کنار هم ببین.</small></div><button type="button" class="primary small" data-cart-compare-all>مقایسه کالاها ⇄</button></div>`+cart.map((item,index)=>{const p=productById(item.id);if(!p)return "";const alreadyCompared=getCompareIds().includes(String(p.id));return `<div class="cart-item"><div class="cart-thumb">${escapeHtml(p.emoji||"📦")}</div><div class="cart-item-main"><b>${escapeHtml(p.name)}</b>${item.variantLabel?`<small>نسخه انتخابی: ${escapeHtml(item.variantLabel)}</small>`:""}${item.color&&!item.variantLabel?`<small>رنگ انتخابی: ${escapeHtml(item.color)}</small>`:""}${item.insuranceCompanyId?`<small>🛡 بیمه: ${escapeHtml(item.insuranceCompanyName)} · ${money(item.insurancePrice)}</small>`:""}<small>${money((Number(item.unitPrice)||p.price)+Number(item.insurancePrice||0))}</small><div class="cart-item-actions"><button class="qty-btn" data-qty-index="${index}" data-delta="-1">−</button><strong>${digits(item.qty)}</strong><button class="qty-btn" data-qty-index="${index}" data-delta="1" ${item.qty>=p.stock?"disabled":""}>+</button><button class="outline small" data-cart-compare="${escapeHtml(p.id)}">${alreadyCompared?"✓ در مقایسه":"⇄ مقایسه"}</button><button class="outline small" data-save-for-later="${p.id}">ذخیره برای بعد</button><button class="remove-item" data-remove-index="${index}">حذف</button></div></div></div>`}).join(""):`<div class="empty-state"><b>🛍️</b>سبد خریدت هنوز خالی است.<br><small>یک محصول جذاب انتخاب کن!</small></div>`;
 $("#cartSubtotal").textContent=money(subtotal());$("#shippingCost").textContent=shipping()===0?(subtotal()?"رایگان":"—"):money(shipping());$("#discountAmount").textContent=money(discountValue());$("#cartTotal").textContent=money(total());
}
function addToCart(id,color="",insurance=null,variant=null){if(!currentUser){toast("برای خرید ابتدا وارد حساب شو یا ثبت‌نام کن.");openAccount();return;}const p=productById(id);if(!p||p.stock<=0)return toast("این محصول موجود نیست.");const variantColor=String(variant?.color||color||"").trim(),unitPrice=Math.max(0,Number(variant?.price)||Number(p.price)||0),variantLabel=variant?`رم ${variant.ram} گیگابایت · حافظه ${variant.storage} گیگابایت · ${variant.color}`:"",ins=insurance&&insurance.companyId?{insuranceCompanyId:String(insurance.companyId),insuranceCompanyName:String(insurance.companyName||""),insurancePrice:Math.max(0,Number(insurance.price)||0),insuranceDescription:String(insurance.description||"")}:{insuranceCompanyId:"",insuranceCompanyName:"",insurancePrice:0,insuranceDescription:""};const found=cart.find(x=>x.id===p.id&&String(x.variantLabel||"")===variantLabel&&String(x.insuranceCompanyId||"")===ins.insuranceCompanyId);if(found){if(found.qty>=p.stock)return toast("بیشتر از موجودی انبار نمی‌توان افزود.");found.qty++}else cart.push({id:p.id,qty:1,unitPrice,...(variantLabel?{variantLabel}:{}),...(variant?{ram:variant.ram,storage:variant.storage,variantStock:variant.stock}:{}),...(variantColor?{color:variantColor}:{}),...ins});save();renderCart();toast(variantLabel?`نسخه ${variantLabel} به سبد خرید اضافه شد.`:ins.insuranceCompanyId?`محصول با بیمه ${ins.insuranceCompanyName} به سبد خرید اضافه شد.`:variantColor?`محصول با رنگ ${variantColor} به سبد خرید اضافه شد.`:"محصول به سبد خرید اضافه شد.");}
// Public, explicitly simulated product actions used by customer-bot.js. These never alter real customer carts or real sales.
function recordBotProductAction(action, productId, detail={}, actor={}){
 const product=productById(productId);if(!product)return false;
 let data={};try{data=JSON.parse(localStorage.getItem("novin_bot_data")||"{}")}catch{}
 if(!Array.isArray(data.productActions))data.productActions=[];if(!Array.isArray(data.activity))data.activity=[];
 const time=Number(actor.time)||Date.now(),id=`BOT-PRODUCT-${time}-${Math.random().toString(36).slice(2,7)}`;
 const row={id,action,productId:product.id,productName:product.name,detail,phone:String(actor.phone||""),name:String(actor.name||"ربات آزمایشی"),bot:true,simulated:true,site:"main",time};
 data.productActions.unshift(row);data.productActions=data.productActions.slice(0,3000);
 data.activity.push({...row,action:`🤖 [ربات آزمایشی] ${action} · ${product.name} · ${typeof detail==="string"?detail:JSON.stringify(detail)}`});data.activity=data.activity.slice(-1500);
 localStorage.setItem("novin_bot_data",JSON.stringify(data));window.dispatchEvent(new CustomEvent("novin-bot-updated"));return row;
}
window.NovinProductActions={
 record:recordBotProductAction,
 browseCategory:(category,actor={})=>{let d={};try{d=JSON.parse(localStorage.getItem("novin_bot_data")||"{}")}catch{}if(!Array.isArray(d.activity))d.activity=[];const row={id:`BOT-CATEGORY-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,action:"مشاهده دسته‌بندی",category:String(category||""),phone:String(actor.phone||""),name:String(actor.name||"ربات آزمایشی"),bot:true,simulated:true,site:"main",time:Date.now()};d.activity.push({...row,action:`🤖 [ربات آزمایشی] مشاهده دسته‌بندی ${row.category}`});d.activity=d.activity.slice(-1500);localStorage.setItem("novin_bot_data",JSON.stringify(d));window.dispatchEvent(new CustomEvent("novin-bot-updated"));return row;},
 favorite:(id,actor)=>recordBotProductAction("افزودن/حذف علاقه‌مندی",id,"تغییر فهرست علاقه‌مندی آزمایشی",actor),
 compare:(id,actor)=>{const row=recordBotProductAction("مقایسه محصول",id,"افزودن به فهرست مقایسه آزمایشی",actor);if(!row)return false;let d={};try{d=JSON.parse(localStorage.getItem("novin_bot_data")||"{}")}catch{}if(!Array.isArray(d.compareLists))d.compareLists=[];let list=d.compareLists.find(x=>x.phone===row.phone);if(!list){list={phone:row.phone,name:row.name,bot:true,productIds:[],updatedAt:row.time};d.compareLists.push(list);}if(!list.productIds.map(String).includes(String(id))&&list.productIds.length<4)list.productIds.push(id);list.updatedAt=row.time;localStorage.setItem("novin_bot_data",JSON.stringify(d));return row;},
 priceAlert:(id,actor)=>{const row=recordBotProductAction("پیگیری قیمت",id,"فعال‌سازی هشدار قیمت آزمایشی",actor);if(!row)return false;let d={};try{d=JSON.parse(localStorage.getItem("novin_bot_data")||"{}")}catch{}if(!Array.isArray(d.priceWatchers))d.priceWatchers=[];if(!d.priceWatchers.some(x=>x.phone===row.phone&&String(x.productId)===String(id)))d.priceWatchers.push({phone:row.phone,name:row.name,productId:id,productName:row.productName,bot:true,simulated:true,createdAt:row.time});localStorage.setItem("novin_bot_data",JSON.stringify(d));return row;},
 selectColor:(id,color,actor)=>recordBotProductAction("انتخاب رنگ",id,{color:String(color||"")},actor),
 addToCart:(id,color,actor)=>recordBotProductAction("افزودن به سبد آزمایشی",id,{color:String(color||"طبق موجودی"),quantity:1},actor),
 askQuestion:(id,question,actor)=>{const row=recordBotProductAction("ثبت پرسش",id,{question:String(question||"")},actor);if(!row)return false;let data={};try{data=JSON.parse(localStorage.getItem("novin_bot_data")||"{}")}catch{}if(!Array.isArray(data.productQuestions))data.productQuestions=[];data.productQuestions.unshift({id:row.id,productId:row.productId,productName:row.productName,phone:row.phone,name:row.name,text:String(question||"سؤال آزمایشی درباره محصول"),createdAt:row.time,answer:"",bot:true,simulated:true});data.productQuestions=data.productQuestions.slice(0,2000);localStorage.setItem("novin_bot_data",JSON.stringify(data));return row;},
 viewImage:(id,index,actor)=>recordBotProductAction("مشاهده تصویر گالری",id,{imageIndex:Number(index)||0},actor),
 openTab:(id,tab,actor)=>recordBotProductAction("مشاهده بخش جزئیات",id,{tab:String(tab||"specs")},actor),
 voteReview:(id,actor)=>recordBotProductAction("رأی مفید بودن دیدگاه",id,{reviewId:String(id)},actor),
 share:(id,actor)=>recordBotProductAction("اشتراک‌گذاری محصول",id,"اشتراک‌گذاری آزمایشی",actor)
};

function openCart(){$("#cartOverlay").classList.add("show");$("#cartDrawer").classList.add("open")}
function closeCart(){$("#cartOverlay").classList.remove("show");$("#cartDrawer").classList.remove("open")}
function openModal(html){$("#modalContent").innerHTML=html;$("#modalBackdrop").classList.add("show")}
function closeModal(){
 const productFormEl=$("#productForm");
 if(productFormEl&&!productFormCommitInProgress){
  if(productFormEl.dataset.autoSavePending==="1")return;
  if(!productFormEl.reportValidity())return;
  productFormEl.dataset.autoSavePending="1";
  productFormEl.requestSubmit();
  return;
 }
 $("#modalBackdrop").classList.remove("show");
}
function switchView(view){$("#storeView").classList.toggle("hidden",view!=="store");$("#adminView").classList.toggle("hidden",view!=="admin");$(".topbar")?.classList.toggle("hidden",view!=="store");$(".category-nav")?.classList.toggle("hidden",view!=="store");if(view==="admin"){renderAdmin(currentAdminPanel);window.scrollTo(0,0)}else {renderStoreAnnouncements();window.scrollTo(0,0)}}
function notifyFreeFireCustomer(order, status){if(!order||!(order.type==="freefire_topup"||order.game==="Free Fire")||!order.customer?.phone)return;try{const key="novin_gems_inbox",list=JSON.parse(localStorage.getItem(key)||"[]"),labels={pending:"در انتظار پرداخت",paid:"پرداخت‌شده",processing:"در حال آماده‌سازی",sent:"ارسال‌شده",delivered:"تحویل‌شده",cancel:"لغوشده"};list.push({id:Date.now()+Math.random(),phone:String(order.customer.phone),from:"admin",text:`وضعیت سفارش جم ${order.number||order.id} به «${labels[status]||status}» تغییر کرد.`,orderNumber:order.number||"",time:Date.now()});localStorage.setItem(key,JSON.stringify(list.slice(-500)));}catch(err){console.warn("Free Fire notification could not be saved",err?.message||err)}}
function statusLabel(status){const map={pending:["در انتظار پرداخت","wait"],paid:["پرداخت‌شده","paid"],processing:["در حال آماده‌سازی","wait"],sent:["ارسال‌شده","sent"],delivered:["تحویل‌شده","delivered"],cancel:["لغوشده","cancel"]};const x=map[status]||map.pending;return `<span class="status ${x[1]}">${x[0]}</span>`}
function orderRows(list){return list.length?list.slice().sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0)).map(o=>`<tr><td>#${escapeHtml(o.number)}<small style="display:block;color:var(--muted)">${new Date(o.createdAt||Date.now()).toLocaleString("fa-IR")}</small>${o.simulated||o.bot?`<small style="display:block;color:#a12aa5">ربات / خرید آزمایشی · ${escapeHtml(o.simulationSite==="gem"?"فروشگاه جم":"نوین‌شاپ")}</small>`:""}</td><td>${escapeHtml(o.customer?.name||"مشتری")}<small style="display:block;color:var(--muted)">${escapeHtml(o.customer?.phone||"")}</small></td><td>${(o.items||[]).map(i=>`${escapeHtml(i.name||"کالا")} × ${digits(i.qty||i.quantity||1)}${i.color?` · رنگ: ${escapeHtml(i.color)}`:""}`).join("<br>")||"—"}</td><td>${money(o.total)}</td><td>${statusLabel(o.status)}</td><td><button class="table-action" data-order-details="${escapeHtml(o.id)}">جزئیات کامل</button> <button class="table-action" data-invoice="${escapeHtml(o.id)}">فاکتور</button> <button class="table-action" data-next-order-status="${escapeHtml(o.id)}">مرحله بعد</button></td></tr>`).join(""):`<tr><td colspan="6" class="empty-admin">هنوز سفارشی ثبت نشده است.</td></tr>`}
function productRows(list){return list.map(p=>`<tr><td><div class="table-product"><span class="table-emoji">${escapeHtml(p.emoji||"📦")}</span><span>${escapeHtml(p.name)}<small class="sku-line">${escapeHtml(p.sku||"")}</small></span></div></td><td>${escapeHtml(p.category)}</td><td>${money(p.price)}</td><td>${digits(p.stock)}<small class="sku-line">حد هشدار: ${digits(p.minStock??5)}</small></td><td><span class="admin-rating-value">★ ${Number(p.rating||0).toFixed(1)}</span></td><td>${p.insuranceEnabled?`<span class="status paid">فعال · ${money(Number(p.insurancePrice)||0)}</span>`:`<span class="status wait">بدون بیمه</span>`}</td><td>${p.published===false?'<span class="status wait">پیش‌نویس</span>':p.stock<=(p.minStock??5)?'<span class="status cancel">کمبود موجودی</span>':'<span class="status paid">منتشرشده</span>'}${p.featured?'<small class="sku-line">★ ویژه</small>':''}</td><td><button class="table-action" data-edit="${p.id}">ویرایش</button> <button class="table-action" data-duplicate-product="${p.id}">تکثیر</button> <button class="table-action" data-toggle-featured="${p.id}">${p.featured?'لغو ویژه':'ویژه‌کردن'}</button> <button class="table-action" data-toggle-published="${p.id}">${p.published===false?'انتشار':'پیش‌نویس'}</button> <button class="table-action" data-stock-adjust="${p.id}">اصلاح موجودی</button> <button class="danger-btn" data-delete="${p.id}">حذف</button></td></tr>`).join("")}
function overviewHtml(){
 const revenue=orders.filter(o=>o.status!=="cancel"&&o.status!=="pending").reduce((s,o)=>s+o.total,0), pending=orders.filter(o=>!['delivered','completed','cancel'].includes(o.status)).length;
 const counts=[orders.length,cartQty(),products.length,customers.length];
 const lastOrders=orders.slice(-5).reverse();
 const top=products.slice().sort((a,b)=>b.price-a.price).slice(0,4);
 const daily=Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(6-i));const next=new Date(d);next.setDate(next.getDate()+1);return {label:d.toLocaleDateString("fa-IR",{weekday:"short"}),value:orders.filter(o=>o.status!=="cancel"&&o.status!=="pending"&&Number(o.createdAt)>=d.getTime()&&Number(o.createdAt)<next.getTime()).reduce((sum,o)=>sum+Number(o.total||0),0)}});const maxDaily=Math.max(1,...daily.map(x=>x.value));const bars=daily.map(x=>({height:Math.max(4,x.value/maxDaily*100),label:x.label,value:x.value}));
 return `<div class="stats-grid"><div class="stat-card"><div class="stat-top">فروش ثبت‌شده <span class="stat-icon">↗</span></div><div class="stat-value">${money(revenue)}</div><div class="stat-note">مجموع سفارش‌های پرداخت‌شده</div></div><div class="stat-card"><div class="stat-top">سفارش‌ها <span class="stat-icon">▤</span></div><div class="stat-value">${digits(counts[0])}</div><div class="stat-note">${digits(pending)} سفارش نیازمند بررسی</div></div><div class="stat-card"><div class="stat-top">محصولات <span class="stat-icon">▣</span></div><div class="stat-value">${digits(counts[2])}</div><div class="stat-note">${digits(products.filter(p=>p.stock<=5).length)} محصول با موجودی کم</div></div><div class="stat-card"><div class="stat-top">مشتریان <span class="stat-icon">♙</span></div><div class="stat-value">${digits(counts[3])}</div><div class="stat-note">مشتریان ثبت‌شده در این مرورگر</div></div></div>
 <div class="admin-columns"><div class="panel-card"><div class="panel-head"><h3>نمایش روند فروش</h3><span class="eyebrow">نمایش نمونه</span></div><div class="chart">${bars.map(x=>`<div class="chart-col" title="${escapeHtml(x.label)}: ${money(x.value)}"><div class="chart-bar" style="height:${x.height}%"></div><span>${escapeHtml(x.label)}</span></div>`).join("")}</div><p class="muted">نمودار بر اساس سفارش‌های ثبت‌شده و پرداخت‌شده همین مرورگر در ۷ روز اخیر محاسبه می‌شود.</p></div><div class="panel-card"><div class="panel-head"><h3>محصولات گران‌تر</h3><button data-panel-link="products">مدیریت محصولات ←</button></div><div class="mini-list">${top.map(p=>`<div class="mini-row"><span class="mini-icon">${escapeHtml(p.emoji)}</span><div class="mini-info"><b>${escapeHtml(p.name)}</b><small>${digits(p.stock)} عدد در انبار</small></div><strong>${money(p.price)}</strong></div>`).join("")}</div></div></div>
 <div class="panel-card"><div class="panel-head"><h3>آخرین سفارش‌ها</h3><button data-panel-link="orders">مشاهده همه ←</button></div><div class="table-wrap"><table><thead><tr><th>شماره</th><th>مشتری</th><th>تعداد</th><th>مبلغ</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${orderRows(lastOrders)}</tbody></table></div></div><div class="admin-columns"><div class="panel-card"><div class="panel-head"><h3>دسترسی سریع انبار</h3><button data-panel-link="inventory">رفتن به انبار ←</button></div><p class="muted">محصولات نیازمند شارژ موجودی را یک‌جا ببین و مستقیم وارد مدیریت انبار شو.</p><div class="mini-list">${products.filter(p=>Number(p.stock||0)<=Number(p.minStock??5)).slice(0,4).map(p=>`<div class="mini-row"><span class="mini-icon">${escapeHtml(p.emoji||"📦")}</span><div class="mini-info"><b>${escapeHtml(p.name)}</b><small>موجودی ${digits(p.stock)} · حد هشدار ${digits(p.minStock??5)}</small></div><button class="table-action" data-stock-add="${escapeHtml(p.id)}" data-stock-amount="5">+5</button></div>`).join("")||'<p class="muted">همه محصولات بالاتر از حد هشدار هستند.</p>'}</div></div><div class="panel-card"><div class="panel-head"><h3>مرکز اقدام‌های مدیریتی</h3></div><div class="quick-actions-grid"><button class="primary" data-panel-link="inventory">＋ افزایش موجودی</button><button class="outline" data-panel-link="reports">▥ مشاهده ۵ نمودار گزارش</button><button class="outline" data-panel-link="orders">▤ بررسی سفارش‌ها</button><button class="outline" data-panel-link="products">▣ مدیریت محصولات</button></div><p class="muted">قابلیت جدید: دسترسی مستقیم به کارهای پرتکرار و هشدار موجودی از نمای کلی.</p></div></div><div class="panel-card"><div class="panel-head"><h3>پشتیبان‌گیری و بازیابی</h3><span class="eyebrow">ذخیره محلی</span></div><p class="muted">محصولات، سفارش‌ها، مشتریان، پیام‌ها، کیف پول و تنظیمات در مرورگر فعلی ذخیره می‌شوند. برای جلوگیری از ازدست‌رفتن داده‌ها، مرتب فایل پشتیبان بگیر. فایل شامل اطلاعات مشتریان است و باید خصوصی نگه داشته شود.</p><div class="toolbar-left"><button class="primary small" id="exportFullBackup">دانلود فایل پشتیبان کامل</button><button class="outline small" id="importFullBackup">بازیابی از فایل پشتیبان</button><input id="backupFileInput" type="file" accept="application/json,.json" hidden></div></div>`;
}
function productsAdminHtml(){
 const needsImages=adminProductQuery==="__needs_images__";
 const categories=[...new Set(products.map(p=>String(p.category||"بدون دسته‌بندی").trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"fa"));
 const list=products.filter(p=>{
  const imgs=[...new Set([...(Array.isArray(p.images)?p.images:[]),p.image].filter(Boolean))];
  const imageMatch=needsImages?imgs.length<=2:true;
  const categoryMatch=adminProductCategory==="همه"||String(p.category||"بدون دسته‌بندی")===adminProductCategory;
  const queryMatch=needsImages||(`${p.name} ${p.category} ${p.brand||""} ${p.model||""}`).toLowerCase().includes(adminProductQuery.toLowerCase());
  return imageMatch&&categoryMatch&&queryMatch;
 });
 return `<div class="admin-toolbar"><input id="adminProductSearch" placeholder="جست‌وجوی محصولات..." value="${needsImages?"":escapeHtml(adminProductQuery)}"><div class="toolbar-left"><button class="outline ${needsImages?"active":""}" id="showProductsFewImages">🖼 محصولات با حداکثر ۲ عکس (${digits(products.filter(p=>[...new Set([...(Array.isArray(p.images)?p.images:[]),p.image].filter(Boolean))].length<=2).length)})</button><button class="outline" id="exportProducts">خروجی CSV</button><button class="outline" id="bulkPriceUpdate">تغییر گروهی قیمت</button><button class="outline" id="showStockAlerts">هشدار موجودی</button><button class="primary small" id="addProductBtn">＋ افزودن محصول</button></div></div>
 <div class="admin-product-category-filter" role="group" aria-label="فیلتر دسته‌بندی محصولات"><button type="button" class="admin-category-chip ${adminProductCategory==="همه"?"active":""}" data-admin-product-category="همه">همه محصولات <span>${digits(products.length)}</span></button>${categories.map(c=>`<button type="button" class="admin-category-chip ${adminProductCategory===c?"active":""}" data-admin-product-category="${escapeHtml(c)}">${escapeHtml(c)} <span>${digits(products.filter(p=>String(p.category||"بدون دسته‌بندی")===c).length)}</span></button>`).join("")}</div>
 <div class="panel-card"><div class="panel-head"><h3>فهرست محصولات (${digits(list.length)})</h3><span class="muted">${adminProductCategory==="همه"?"همه دسته‌بندی‌ها":`دسته‌بندی: ${escapeHtml(adminProductCategory)}`} · تغییرات در همین مرورگر ذخیره می‌شود.</span></div><div class="table-wrap"><table><thead><tr><th>محصول</th><th>دسته‌بندی</th><th>قیمت</th><th>موجودی</th><th>امتیاز</th><th>بیمه</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${productRows(list)||'<tr><td colspan="8">محصولی در این دسته‌بندی یافت نشد.</td></tr>'}</tbody></table></div></div>`;
}
function ordersAdminHtml(){return `<div class="admin-toolbar"><input id="adminOrderSearch" placeholder="جست‌وجوی شماره سفارش، مشتری یا موبایل"><select id="adminOrderStatus"><option value="all">همه وضعیت‌ها</option><option value="pending">در انتظار پرداخت</option><option value="paid">پرداخت‌شده</option><option value="processing">در حال آماده‌سازی</option><option value="sent">ارسال‌شده</option><option value="delivered">تحویل‌شده</option><option value="cancel">لغوشده</option></select><span class="muted">مدیریت وضعیت و جزئیات سفارش‌ها</span><button class="outline" id="exportOrders">خروجی سفارش‌ها CSV</button><button class="outline" id="printOrders">چاپ فهرست</button><button class="danger-btn" id="clearMainOrderHistory">حذف تاریخچه سفارش‌های نوین‌شاپ</button></div><div class="panel-card"><div class="panel-head"><h3>همه سفارش‌ها (${digits(orders.length)})</h3></div><div class="table-wrap"><table><thead><tr><th>شماره</th><th>مشتری</th><th>اقلام</th><th>مبلغ</th><th>وضعیت</th><th>جزئیات</th></tr></thead><tbody>${orderRows(orders)}</tbody></table></div></div>`}

function saveDeliveryManagementForm(form){
 if(!form)return false;
 const id=form.dataset.deliveryForm,o=orders.find(x=>String(x.id)===String(id));
 if(!o){toast("سفارش پیدا نشد؛ فهرست را تازه‌سازی کن.");return false;}
 try{
  const f=new FormData(form),company=String(f.get("company")||""),oldStatus=o.status;
  o.delivery={...(o.delivery||{}),method:String(f.get("method")||"post"),company,companyName:shippingCompanies.find(c=>String(c.id)===company)?.name||"",date:String(f.get("date")||""),time:String(f.get("time")||"").trim(),tracking:String(f.get("tracking")||"").trim(),fee:Math.max(0,Number(f.get("fee")||0)),package:String(f.get("package")||"pending"),notes:String(f.get("notes")||"").trim(),customerNote:String(f.get("customerNote")||"").trim(),updatedAt:Date.now()};
  o.shippingProvider=o.delivery.companyName||o.shippingProvider||"";o.trackingCode=o.delivery.tracking||o.trackingCode||"";o.deliveryDate=o.delivery.date||o.deliveryDate||"";o.deliverySlot=o.delivery.time||o.deliverySlot||"";
  const nextStatus=String(f.get("status")||o.status);if(nextStatus!==oldStatus){o.status=nextStatus;o.updatedAt=Date.now();if(!Array.isArray(o.timeline))o.timeline=[];o.timeline.push({status:nextStatus,at:Date.now(),note:"به‌روزرسانی از بخش تحویل کالاها"});}
  if(!save())throw new Error("ذخیره‌سازی مرورگر ناموفق بود.");
  renderAdmin("delivery");toast("اطلاعات تحویل و ارسال با موفقیت ثبت شد.");return true;
 }catch(err){console.error("Delivery form save failed",err);toast(err.message||"ثبت اطلاعات ناموفق بود؛ فضای ذخیره‌سازی را بررسی کن.");return false;}
}
function deliveryAdminHtml(){
 const list=orders.filter(o=>!(o.type==="freefire_topup"||o.game==="Free Fire")).slice().sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0));
 const active=list.filter(o=>!['delivered','completed','cancel'].includes(o.status)).length;
 const sent=list.filter(o=>o.status==='sent').length,done=list.filter(o=>['delivered','completed'].includes(o.status)).length;
 const companies=shippingCompanies.filter(c=>c.active);
 return `<div class="stats-grid"><div class="stat-card"><div class="stat-top">سفارش‌های قابل تحویل <span class="stat-icon">📦</span></div><div class="stat-value">${digits(active)}</div><div class="stat-note">نیازمند اقدام مدیر</div></div><div class="stat-card"><div class="stat-top">در مسیر ارسال <span class="stat-icon">🚚</span></div><div class="stat-value">${digits(sent)}</div><div class="stat-note">ارسال شده و تحویل نشده</div></div><div class="stat-card"><div class="stat-top">تحویل نهایی <span class="stat-icon">✓</span></div><div class="stat-value">${digits(done)}</div><div class="stat-note">سفارش‌های تکمیل‌شده</div></div></div>
 <div class="panel-card"><div class="panel-head"><div><h3>تحویل کالاها به مشتری</h3><p class="muted">برای هر سفارش روش ارسال، شرکت پستی، زمان تحویل، کد رهگیری و دستورهای بسته‌بندی را تعیین کن. اطلاعات با سفارش ذخیره می‌شود.</p></div><button type="button" class="outline small" id="refreshDeliveryOrders">تازه‌سازی</button></div>
 <div class="delivery-order-list">${list.map(o=>{const d=o.delivery||{},customer=o.customer||{},items=Array.isArray(o.items)?o.items:[];return `<article class="delivery-order-card"><div class="delivery-order-head"><div><span class="eyebrow">سفارش #${escapeHtml(o.number||o.id)}</span><h3>${escapeHtml(customer.name||'مشتری')}</h3><p class="muted">${escapeHtml(customer.phone||'شماره تماس ثبت نشده')} · ثبت ${new Date(o.createdAt||Date.now()).toLocaleString('fa-IR')}</p></div><div>${statusLabel(o.status)}<div class="delivery-action-buttons"><button type="button" class="primary small" data-delivery-send="${escapeHtml(o.id)}" ${["sent","delivered","completed","cancel"].includes(o.status)?"disabled":""}>🚚 ثبت ارسال</button>${o.status==='sent'?`<button type="button" class="outline small" data-delivery-complete="${escapeHtml(o.id)}">✓ تأیید تحویل به مشتری</button>`:''}<button type="button" class="outline small" data-order="${escapeHtml(o.id)}">جزئیات سفارش</button></div><p class="muted">مبلغ کل: <b>${money(o.total||0)}</b></p></div></div>
 <details class="delivery-order-expand"><summary>مشاهده مشخصات کالا و تنظیمات ارسال</summary><div class="delivery-order-details"><div><h4>اقلام سفارش</h4>${items.map(i=>{const product=productById(i.id)||{};return `<div class="delivery-item"><span>${escapeHtml(product.emoji||'📦')}</span><div><b>${escapeHtml(i.name||product.name||'محصول حذف‌شده')}</b><small>${digits(i.qty||1)} عدد · هر عدد ${money(i.price??product.price??0)}</small><small>کد کالا: ${escapeHtml(product.sku||i.sku||'—')} · دسته: ${escapeHtml(product.category||'—')}</small></div><strong>${money(Number(i.price??product.price??0)*Number(i.qty||1))}</strong></div>`}).join('')||'<p class="muted">جزئیات اقلام در سفارش ثبت نشده است.</p>'}</div><div><h4>اطلاعات مشتری و نشانی</h4><p><b>نام:</b> ${escapeHtml(customer.name||'—')}</p><p><b>موبایل:</b> ${escapeHtml(customer.phone||'—')}</p><p><b>ایمیل:</b> ${escapeHtml(customer.email||'—')}</p><p><b>نشانی:</b> ${escapeHtml(customer.address||o.address||'نشانی در سفارش ثبت نشده')}</p><p><b>کد پستی:</b> ${escapeHtml(customer.postalCode||o.postalCode||'—')}</p><p><b>پرداخت:</b> ${escapeHtml(o.paymentMethod||o.payment?.method||'طبق سفارش')} · ${statusLabel(o.status)}</p></div></div>
 <form class="delivery-management-form" data-delivery-form="${escapeHtml(o.id)}"><div class="form-grid"><div class="field"><label>روش تحویل</label><select name="method"><option value="post" ${d.method==='post'?'selected':''}>پست پیشتاز</option><option value="express" ${d.method==='express'?'selected':''}>پست سفارشی / اقتصادی</option><option value="tipax" ${d.method==='tipax'?'selected':''}>تیپاکس</option><option value="courier" ${d.method==='courier'?'selected':''}>پیک شهری</option><option value="pickup" ${d.method==='pickup'?'selected':''}>تحویل حضوری</option></select></div><div class="field"><label>شرکت ارسال</label><select name="company"><option value="">انتخاب شرکت</option>${companies.map(c=>`<option value="${escapeHtml(c.id)}" ${d.company===c.id?'selected':''}>${escapeHtml(c.name)} · ${money(c.fee)}</option>`).join('')}</select></div><div class="field"><label>وضعیت آماده‌سازی/تحویل</label><select name="status"><option value="paid" ${o.status==='paid'?'selected':''}>پرداخت‌شده</option><option value="processing" ${o.status==='processing'?'selected':''}>در حال آماده‌سازی</option><option value="sent" ${o.status==='sent'?'selected':''}>تحویل به شرکت ارسال</option><option value="delivered" ${o.status==='delivered'?'selected':''}>تحویل‌شده به مشتری</option><option value="cancel" ${o.status==='cancel'?'selected':''}>لغوشده</option></select></div><div class="field"><label>تاریخ تخمینی تحویل</label><input name="date" type="date" value="${escapeHtml(d.date||'')}"></div><div class="field"><label>بازه زمانی تحویل</label><input name="time" placeholder="مثلاً ۱۴ تا ۱۸" value="${escapeHtml(d.time||'')}"></div><div class="field"><label>کد رهگیری مرسوله</label><input name="tracking" dir="ltr" placeholder="کد رهگیری" value="${escapeHtml(d.tracking||'')}"></div><div class="field"><label>هزینه ارسال (تومان)</label><input name="fee" type="number" min="0" value="${Number.isFinite(Number(d.fee))?Number(d.fee):Number(shipping())}"></div><div class="field"><label>وضعیت بسته‌بندی</label><select name="package"><option value="pending" ${d.package==='pending'?'selected':''}>بسته‌بندی نشده</option><option value="packed" ${d.package==='packed'?'selected':''}>بسته‌بندی آماده</option><option value="checked" ${d.package==='checked'?'selected':''}>کنترل نهایی انجام شد</option></select></div><div class="field full-field"><label>یادداشت داخلی مدیر / دستور بسته‌بندی</label><textarea name="notes" rows="2" placeholder="مثلاً بسته‌بندی ضدضربه، تماس قبل از ارسال...">${escapeHtml(d.notes||'')}</textarea></div><div class="field full-field"><label>توضیح قابل نمایش برای مشتری</label><textarea name="customerNote" rows="2" placeholder="توضیح درباره زمان یا شرایط تحویل">${escapeHtml(d.customerNote||'')}</textarea></div></div><div class="delivery-form-footer"><small class="muted">آخرین ذخیره: ${d.updatedAt?new Date(d.updatedAt).toLocaleString('fa-IR'):'هنوز ثبت نشده'}</small><button type="button" class="primary small" data-delivery-save="${escapeHtml(o.id)}">ثبت و ارسال اطلاعات</button></div></form><div class="shipping-evidence-box"><h4>مدارک بسته و کنترل سلامت</h4><form class="package-photo-form" data-package-photo="${escapeHtml(o.id)}"><div class="field"><label>عکس بسته قبل از ارسال (JPG/PNG/WEBP، حداکثر ۵ مگابایت)</label><input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></div><div class="field"><label>توضیح عکس (اختیاری)</label><input name="note" placeholder="مثلاً بسته‌بندی و پلمب قبل از تحویل به پست"></div><button type="submit" class="outline small">📷 ثبت عکس خصوصی روی سرور</button><small class="muted" data-photo-status="${escapeHtml(o.id)}"></small></form><form class="damage-report-form" data-damage-report="${escapeHtml(o.id)}"><div class="form-grid"><div class="field"><label>وضعیت هنگام تحویل/بازرسی</label><select name="condition"><option value="unknown">هنوز بررسی نشده</option><option value="intact">بسته سالم گزارش شد</option><option value="damaged">آسیب‌دیدگی بسته</option><option value="missing-items">کسری کالا</option></select></div><div class="field"><label>شرح گزارش</label><input name="description" required placeholder="شرح وضعیت، زمان و شواهد"></div></div><button type="submit" class="outline small">ثبت گزارش سلامت/آسیب</button><small class="muted">گزارش داخلی فروشگاه است؛ تأیید رسمی پست محسوب نمی‌شود.</small></form></div></details></article>`}).join('')||'<div class="empty-admin">هنوز سفارش کالایی برای تحویل وجود ندارد.</div>'}</div></div>`;
}

function renderParcelLookupResult(o,root){if(!root)return;if(!o){root.innerHTML='<div class="parcel-result is-warning"><b>مرسوله پیدا نشد</b><p>شماره سفارش یا کد رهگیری را دقیق بررسی کن.</p></div>';return;}const d=o.delivery||{},track=d.tracking||o.trackingCode||'',status=o.status==='delivered'||o.status==='completed'?'در فروشگاه به‌عنوان تحویل‌شده ثبت شده':o.status==='sent'?'در فروشگاه به‌عنوان ارسال‌شده ثبت شده':o.status==='cancel'?'سفارش لغو شده':o.status==='processing'?'در حال آماده‌سازی':o.status==='paid'?'پرداخت شده؛ هنوز ارسال ثبت نشده':'در انتظار پرداخت';const official=o.parcelCheck?.carrierStatus||'';root.innerHTML=`<div class="parcel-result ${o.status==='delivered'||o.status==='completed'?'is-success':'is-warning'}"><h3>نتیجه بررسی سفارش #${escapeHtml(o.number||o.id)}</h3><p><b>وضعیت داخلی فروشگاه:</b> ${escapeHtml(status)}</p><p><b>شرکت حمل‌ونقل:</b> ${escapeHtml(d.companyName||o.shippingProvider||'تعیین نشده')}</p><p><b>کد رهگیری:</b> <span dir="ltr">${escapeHtml(track||'ثبت نشده')}</span></p><p><b>تاریخ تخمینی تحویل:</b> ${escapeHtml(d.date||o.deliveryDate||'تعیین نشده')} ${escapeHtml(d.time||o.deliverySlot||'')}</p><p><b>توضیح ارسال‌کننده:</b> ${escapeHtml(d.customerNote||'ثبت نشده')}</p><p><b>نتیجه ثبت‌شده شرکت حمل‌ونقل:</b> ${escapeHtml(official||'داده رسمی دریافت نشده')}</p><p class="muted">این نتیجه بر اساس اطلاعات فروشگاه است. بدون اتصال رسمی شرکت حمل‌ونقل، نمی‌توان تحویل واقعی را مستقل تأیید کرد.</p>${track?`<button type="button" class="outline" data-live-track="${escapeHtml(o.id)}">استعلام زنده از سرویس متصل</button><div id="liveTrackResult" aria-live="polite"></div>`:""}<form id="parcelCarrierStatusForm" class="form-grid" data-parcel-status-order="${escapeHtml(o.id)}"><div class="field"><label>ثبت نتیجه‌ای که از شرکت حمل‌ونقل بررسی کرده‌ای</label><select name="carrierStatus"><option value="" ${!official?'selected':''}>هنوز بررسی نشده</option><option value="در حال پردازش شرکت حمل‌ونقل" ${official==='در حال پردازش شرکت حمل‌ونقل'?'selected':''}>در حال پردازش</option><option value="در مسیر توزیع" ${official==='در مسیر توزیع'?'selected':''}>در مسیر توزیع</option><option value="تحویل‌شده طبق استعلام شرکت" ${official==='تحویل‌شده طبق استعلام شرکت'?'selected':''}>تحویل‌شده طبق استعلام شرکت</option><option value="عدم تحویل / برگشت مرسوله" ${official==='عدم تحویل / برگشت مرسوله'?'selected':''}>عدم تحویل / برگشت</option><option value="نیازمند پیگیری از شرکت" ${official==='نیازمند پیگیری از شرکت'?'selected':''}>نیازمند پیگیری</option></select></div><div class="field"><label>شماره پیگیری استعلام (اختیاری)</label><input name="reference" value="${escapeHtml(o.parcelCheck?.reference||'')}" placeholder="کد/شماره نتیجه استعلام"></div><div class="field full-field"><label>یادداشت نتیجه استعلام</label><input name="note" value="${escapeHtml(o.parcelCheck?.note||'')}" placeholder="مثلاً تماس با شعبه در تاریخ ..."></div><div class="field full-field"><button class="primary" type="submit">ذخیره نتیجه بررسی</button></div></form></div>`;}
function parcelCheckAdminHtml(){
 const list=orders.filter(o=>!(o.type==="freefire_topup"||o.game==="Free Fire")).slice().sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0));
 const sent=list.filter(o=>o.status==="sent"||o.delivery?.tracking||o.trackingCode);
 return `<div class="panel-card"><div class="panel-head"><div><h3>اتصال رهگیری شرکت ملی پست</h3><p class="muted">استعلام خودکار فقط وقتی فعال می‌شود که آدرس API مورد تأیید/ارائه‌دهنده مجاز و توکن آن در تنظیمات سرور ثبت شده باشد.</p></div><span class="status wait" id="postApiStatus">در حال بررسی تنظیمات…</span></div><div id="postApiMessage" class="muted">در حال خواندن وضعیت اتصال…</div><form id="postLiveTrackForm" class="form-grid"><div class="field"><label>کد رهگیری مرسوله پستی</label><input name="trackingNumber" dir="ltr" required maxlength="80" placeholder="کد رهگیری صادرشده توسط پست"></div><div class="field"><label>استعلام از</label><input value="سرویس API تنظیم‌شده در سرور" readonly></div><div class="field full-field"><button type="submit" class="primary">🌐 استعلام از سرویس متصل</button><a href="https://tracking.post.ir/" target="_blank" rel="noopener">باز کردن سامانه رسمی رهگیری پست ↗</a></div></form><div id="postLiveTrackResult" aria-live="polite"></div><hr><h3>جست‌وجوی سفارش داخل فروشگاه</h3><p class="muted">این جست‌وجو فقط داده‌های محلی سفارش را پیدا می‌کند و با استعلام شرکت پست متفاوت است.</p><form id="parcelLookupForm" class="form-grid"><div class="field"><label>شماره سفارش یا کد رهگیری</label><input name="query" required placeholder="شماره سفارش / کد رهگیری" autocomplete="off"></div><div class="field"><label>شرکت حمل‌ونقل</label><select name="carrier"><option value="auto">تشخیص خودکار از سفارش</option>${shippingCompanies.map(c=>`<option value="${escapeHtml(c.id)}">${escapeHtml(c.name)}</option>`).join('')}</select></div><div class="field full-field"><button type="submit" class="outline">🔎 جست‌وجوی اطلاعات فروشگاه</button></div></form><div id="parcelLookupResult" aria-live="polite"></div><p class="muted">وضعیت تحویل فقط وقتی «تأییدشده از سرویس متصل» نمایش داده می‌شود که پاسخ API تنظیم‌شده یک فیلد وضعیت صریح برگرداند. تخمین زمان تحویل در صورت نبود داده معتبر نمایش داده نمی‌شود.</p></div>
 <div class="panel-card"><div class="panel-head"><div><h3>مرسوله‌های قابل بررسی (${digits(sent.length)})</h3><p class="muted">برای ثبت نتیجه‌ای که از پنل شرکت حمل‌ونقل دریافت کرده‌ای، سفارش را باز کن و وضعیت داخلی را به‌روزرسانی کن.</p></div><button class="outline small" type="button" id="refreshParcelChecks">تازه‌سازی</button></div><div class="delivery-order-list">${sent.map(o=>{const d=o.delivery||{},track=d.tracking||o.trackingCode||"",carrier=d.companyName||o.shippingProvider||"شرکت ارسال تعیین نشده";return `<article class="delivery-order-card parcel-compact-card"><div class="delivery-order-head"><div><span class="eyebrow">سفارش #${escapeHtml(o.number||o.id)}</span><h3>${escapeHtml(o.customer?.name||"مشتری")}</h3><p class="muted">${escapeHtml(carrier)} · کد رهگیری: <b dir="ltr">${escapeHtml(track||"ثبت نشده")}</b></p></div><div>${statusLabel(o.status)}<p class="muted">${track?"کد رهگیری موجود است":"نیازمند ثبت کد رهگیری"}</p></div></div><div class="toolbar-left"><button type="button" class="primary small" data-parcel-lookup-order="${escapeHtml(o.id)}">بررسی این مرسوله</button><button type="button" class="outline small" data-parcel-open-delivery="${escapeHtml(o.id)}">مدیریت ارسال</button></div></article>`}).join("")||'<div class="empty-admin">هنوز مرسوله‌ای با وضعیت ارسال‌شده یا کد رهگیری ثبت نشده است.</div>'}</div></div>`;
}
function customersAdminHtml(){
 const merged=new Map();
 customers.forEach(c=>{if(c?.phone)merged.set(normalizePhone(c.phone),{...c});});
 accounts.forEach(a=>{if(!a?.phone)return;const key=normalizePhone(a.phone),old=merged.get(key)||{};merged.set(key,{...old,...a,phone:a.phone,name:a.name||old.name,email:a.email||old.email,address:a.address||old.address});});
 const list=[...merged.values()].sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0));
 return `<div class="panel-card"><div class="panel-head"><div><h3>پروفایل مشتریان (${digits(list.length)})</h3><p class="muted">حساب‌های ثبت‌نام‌شده و مشتریان دارای سفارش، همراه تصویر پروفایل</p></div><button id="exportCustomers">خروجی CSV</button></div>${list.length?list.slice().reverse().map(c=>{const account=accounts.find(a=>normalizePhone(a.phone)===normalizePhone(c.phone));const avatar=account?.avatar;const count=orders.filter(o=>normalizePhone(o.customer?.phone)===normalizePhone(c.phone)).length;return `<div class="customer-row customer-profile-row">${avatar?`<img class="customer-avatar customer-avatar-img" src="${escapeHtml(avatar)}" alt="تصویر ${escapeHtml(c.name||'مشتری')}">`:`<div class="customer-avatar">${escapeHtml((c.name||"?").slice(0,1))}</div>`}<div class="mini-info"><b>${escapeHtml(c.name||"مشتری")}</b><small>${escapeHtml(c.phone)} · ${escapeHtml(c.email||"ایمیل ثبت نشده")}</small><small>${account?`عضویت: ${new Date(account.createdAt||Date.now()).toLocaleDateString('fa-IR')}`:'حساب کامل ثبت نشده'}</small></div><strong>${digits(count)} سفارش</strong><div class="customer-admin-actions"><button class="table-action" data-customer-manage="${escapeHtml(c.phone)}">مدیریت حساب</button><button class="table-action" data-customer-orders="${escapeHtml(c.phone)}">سفارش‌ها</button><button class="table-action" data-customer-login="${escapeHtml(c.phone)}" ${account?'':'disabled'}>ورود نمایشی</button></div></div>`}).join(''):'<div class="empty-admin">هنوز حساب مشتری ثبت نشده است.</div>'}</div>`;
}
function reviewsAdminHtml(){
 const rows=reviews.slice().sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0));
 return `<div class="panel-card"><div class="panel-head"><div><h3>نظرات مشتریان (${digits(rows.length)})</h3><p class="muted">نظرها همراه نام مشتری، تصویر پروفایل، محصول و امتیاز</p></div></div>${rows.length?rows.map(r=>{const product=productById(r.productId),account=accounts.find(a=>normalizePhone(a.phone)===normalizePhone(r.phone));return `<article class="admin-review-row"><div class="review-avatar">${account?.avatar||r.avatar?`<img src="${escapeHtml(account?.avatar||r.avatar)}" alt="تصویر پروفایل">`:escapeHtml((r.name||'م').slice(0,1))}</div><div class="admin-review-main"><div class="admin-review-meta"><b>${escapeHtml(r.name||'مشتری')}</b><span class="review-stars">${'★'.repeat(Math.max(0,Math.min(5,Number(r.rating)||0)))}${'☆'.repeat(5-Math.max(0,Math.min(5,Number(r.rating)||0)))}</span><small>${new Date(r.createdAt||Date.now()).toLocaleString('fa-IR')}</small></div><small class="muted">${escapeHtml(product?.name||r.productName||'محصول حذف‌شده')} · ${escapeHtml(r.phone||'بدون شماره')} · ${r.bot||r.simulated?'ربات آزمایشی':'مشتری'}</small>${r.title?`<b class="review-title">${escapeHtml(r.title)}</b>`:''}<p>${escapeHtml(r.text||'')}</p></div><button class="danger-btn" data-review-delete="${r.id}">حذف نظر</button></article>`}).join(''):'<div class="empty-admin">هنوز نظری ثبت نشده است.</div>'}</div>`;
}

function sortVisibleReviews(mode="newest"){const list=document.querySelector(".review-list");if(!list)return;const items=[...list.querySelectorAll(".review-item")];items.sort((a,b)=>{const ra=reviews.find(r=>String(r.id)===String(a.dataset.reviewId)),rb=reviews.find(r=>String(r.id)===String(b.dataset.reviewId));if(mode==="highest")return Number(rb?.rating||0)-Number(ra?.rating||0);if(mode==="lowest")return Number(ra?.rating||0)-Number(rb?.rating||0);return Number(rb?.createdAt||0)-Number(ra?.createdAt||0)});items.forEach(item=>list.appendChild(item));}
function userRanksAdminHtml(){
 const merged=new Map();accounts.forEach(a=>{if(a?.phone)merged.set(normalizePhone(a.phone),{name:a.name||"مشتری",phone:a.phone,bot:false})});customers.forEach(c=>{if(c?.phone){const k=normalizePhone(c.phone);merged.set(k,{...(merged.get(k)||{}),name:c.name||merged.get(k)?.name||"مشتری",phone:c.phone,bot:!!c.bot||!!c.simulated})}});
 let bd={};try{bd=JSON.parse(localStorage.getItem("novin_bot_data")||"{}")}catch{};(Array.isArray(bd.botProfiles)?bd.botProfiles:[]).forEach(b=>{if(b?.phone)merged.set(normalizePhone(b.phone),{name:b.name||"ربات آزمایشی",phone:b.phone,bot:true})});
 const rows=[...merged.values()].map(u=>({...u,count:paidOrderCount(u.phone),rank:userRank(u.phone),reviews:reviews.filter(r=>normalizePhone(r.phone)===normalizePhone(u.phone)).length})).sort((a,b)=>b.count-a.count);
 return `<div class="panel-card"><div class="panel-head"><div><h3>مقام کاربران و مشتریان (${digits(rows.length)})</h3><p class="muted">مقام خودکار بر اساس تعداد سفارش‌های پرداخت‌شده محاسبه می‌شود؛ برای مشتریان و ربات‌های آزمایشی قابل مدیریت است.</p></div></div><div class="rank-rules-grid">${USER_RANKS.map(r=>`<div class="rank-rule"><b>${r.label}</b><small>از ${digits(r.min)} محصول خریداری‌شده</small></div>`).join("")}</div><div class="table-wrap"><table class="admin-table"><thead><tr><th>کاربر</th><th>نوع حساب</th><th>محصول خریداری‌شده</th><th>تعداد دیدگاه</th><th>مقام فعلی</th><th>تغییر مقام</th></tr></thead><tbody>${rows.map(u=>`<tr><td><b>${escapeHtml(u.name)}</b><small class="muted" style="display:block" dir="ltr">${escapeHtml(u.phone)}</small></td><td>${u.bot?'🤖 ربات آزمایشی':'مشتری'}</td><td>${digits(u.count)}</td><td>${digits(u.reviews)}</td><td><span class="rank-pill">${u.rank.label}</span></td><td><div class="rank-admin-control"><select data-rank-select="${escapeHtml(u.phone)}"><option value="auto">محاسبه خودکار</option>${USER_RANKS.map(r=>`<option value="${r.key}" ${rankOverrides()[normalizePhone(u.phone)]===r.key?'selected':''}>${r.label}</option>`).join("")}</select><button type="button" class="table-action" data-rank-save="${escapeHtml(u.phone)}">ذخیره</button></div></td></tr>`).join("")||'<tr><td colspan="6">هنوز کاربری برای رتبه‌بندی وجود ندارد.</td></tr>'}</tbody></table></div><p class="muted">با انتخاب «محاسبه خودکار»، مقام دستی حذف می‌شود و دوباره بر اساس خریدهای موفق تعیین خواهد شد. سفارش‌های ربات با برچسب آزمایشی در همین بخش دیده می‌شوند و فروش واقعی محسوب نمی‌شوند.</p></div>`;
}
function messagesAdminHtml(){try{const gi=JSON.parse(localStorage.getItem("novin_gems_inbox")||"[]");for(const gm of gi){const cid="ff:"+String(gm.phone||"guest");if(!messages.some(m=>String(m.id)===String(gm.id))){messages.push({id:gm.id,from:gm.from==="admin"?"admin":"customer",text:gm.text,attachment:gm.attachment||null,phone:gm.phone,conversation:cid,source:"freefire",orderNumber:gm.orderNumber,time:gm.time||Date.now()});}}}catch{}const grouped=[...new Set(messages.map(m=>m.conversation||1))];if(!grouped.includes(selectedConversation))selectedConversation=grouped[0]??1;return `<div class="message-admin-layout"><div class="conversation-list">${grouped.map(id=>`<div class="conversation-item ${id===selectedConversation?"active":""}" data-conversation="${id}"><div class="customer-avatar">م</div><div><b>مشتری ${id===1?"مهمان":id}</b><small>${escapeHtml((messages.filter(m=>(m.conversation||1)===id).slice(-1)[0]||{}).text||"گفت‌وگو")}</small></div></div>`).join("")}</div><div class="admin-chat"><div class="admin-chat-head">گفت‌وگو با مشتری ${selectedConversation===1?"مهمان":escapeHtml(selectedConversation)} <button type="button" class="danger-btn small" id="deleteCurrentConversation">حذف تاریخچه این گفت‌وگو</button></div><div class="admin-chat-body" id="adminChatBody">${messages.filter(m=>(m.conversation||1)===selectedConversation).map(m=>`<div class="chat-msg ${m.from==="admin"?"admin":"customer"}">${m.text?escapeHtml(m.text):""}${messageAttachmentHtml(m.attachment)}<small>${new Date(m.time).toLocaleTimeString("fa-IR",{hour:"2-digit",minute:"2-digit"})}</small></div>`).join("")}</div><form id="adminChatForm" class="admin-chat-compose"><input id="adminChatInput" placeholder="پاسخ مدیر را بنویس..."><label class="chat-file-button" title="Attach a file">📎<input id="adminChatFile" type="file" accept="image/*,.pdf,.txt,.doc,.docx,.xlsx,.csv" hidden></label><span class="chat-file-name" id="adminChatFileName"></span><button class="primary">ارسال</button></form></div></div><p class="muted">این چت در نسخه محلی، پیام‌ها را در مرورگر فعلی ذخیره می‌کند؛ برای گفت‌وگوی آنلاین واقعی به سرور و WebSocket نیاز است.</p>`}
function discountsAdminHtml(){return `<div class="panel-card"><div class="panel-head"><h3>کدهای تخفیف</h3><button class="primary small" id="addDiscount">＋ کد جدید</button></div><div class="table-wrap"><table><thead><tr><th>کد</th><th>درصد تخفیف</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${discounts.map(d=>`<tr><td><b>${escapeHtml(d.code)}</b></td><td>${digits(d.percent)}٪</td><td>${d.active?'<span class="status paid">فعال</span>':'<span class="status cancel">غیرفعال</span>'}</td><td><button class="table-action" data-toggle-discount="${escapeHtml(d.code)}">${d.active?"غیرفعال‌کردن":"فعال‌کردن"}</button> <button class="danger-btn" data-delete-discount="${escapeHtml(d.code)}">حذف</button></td></tr>`).join("")}</tbody></table></div><p class="muted">کدهای نمونه: NOVIN10 و WELCOME5. کدها فقط برای این نسخه آزمایشی هستند.</p></div>`}
function activityAdminHtml(){return `<div class="panel-card"><div class="panel-head"><h3>گزارش ورود، خروج و فعالیت کاربران (${digits(activityLog.length)})</h3><button class="outline" id="exportActivity">خروجی CSV</button></div><p class="muted">این گزارش فقط رویدادهای همین مرورگر را ثبت می‌کند و لاگ امنیتی سرور نیست. برای امنیت، رمز عبور، کد یک‌بارمصرف و اطلاعات ورود محرمانه هرگز در گزارش نمایش داده یا ذخیره نمی‌شوند.</p><div class="table-wrap"><table><thead><tr><th>کاربر</th><th>شماره موبایل</th><th>رویداد</th><th>زمان</th></tr></thead><tbody>${activityLog.slice().reverse().map(x=>`<tr><td>${escapeHtml(x.name)}</td><td>${escapeHtml(x.phone)}</td><td>${escapeHtml(x.action)}</td><td>${new Date(x.time).toLocaleString("fa-IR")}</td></tr>`).join("")||'<tr><td colspan="4" class="empty-admin">هنوز رویدادی ثبت نشده است.</td></tr>'}</tbody></table></div></div>`}
function walletsAdminHtml(){
 const botData=(()=>{try{return JSON.parse(localStorage.getItem("novin_bot_data")||"{}")}catch{return {}}})();
 const botProfiles=(Array.isArray(botData.botProfiles)?botData.botProfiles:[]).filter(p=>p&&p.phone);
 const botTx=(Array.isArray(botData.walletTransactions)?botData.walletTransactions:[]).filter(t=>t&&t.phone);
 const phones=[...new Set([...accounts.map(a=>a.phone),...walletTransactions.map(t=>t.phone),...botProfiles.map(p=>p.phone),...botTx.map(t=>t.phone)].filter(Boolean))];
 const tx=[...walletTransactions.map(t=>({...t,_bot:false})),...botTx.map(t=>({...t,_bot:true}))].sort((a,b)=>Number(b.time||0)-Number(a.time||0));
 return `<div class="panel-card"><div class="panel-head"><h3>کیف پول مشتریان (${digits(phones.length)})</h3><button type="button" class="danger-btn" id="clearWalletHistory">حذف تاریخچه</button></div><p class="muted">تراکنش‌های مشتریان و ربات‌های آزمایشی در یک فهرست نمایش داده می‌شوند. حذف تاریخچه، سوابق را پاک می‌کند اما موجودی فعلی کیف پول‌ها را حفظ می‌کند. تراکنش‌های ربات کاملاً دمو هستند.</p><div class="table-wrap"><table><thead><tr><th>مشتری</th><th>موبایل</th><th>موجودی کیف پول</th><th>تعداد تراکنش</th></tr></thead><tbody>${phones.map(phone=>{const a=accounts.find(x=>normalizePhone(x.phone)===normalizePhone(phone))||{},bot=botProfiles.find(x=>normalizePhone(x.phone)===normalizePhone(phone));const count=tx.filter(t=>normalizePhone(t.phone)===normalizePhone(phone)).length;return `<tr><td>${escapeHtml(a.name||bot?.name||"مشتری")}${bot?` <small class="muted">· ربات آزمایشی</small>`:""}</td><td>${escapeHtml(phone)}</td><td>${money(bot?Number(bot.walletBalance)||0:walletBalance(phone))}${bot?` <small class="muted">· دمو</small>`:""}</td><td>${digits(count)}</td></tr>`}).join("")||'<tr><td colspan="4" class="empty-admin">هنوز کیف پولی وجود ندارد.</td></tr>'}</tbody></table></div><h3>تراکنش‌های کیف پول (${digits(tx.length)})</h3><div class="table-wrap"><table><thead><tr><th>مشتری</th><th>نوع</th><th>مبلغ</th><th>وضعیت</th><th>شماره پیگیری</th><th>تاریخ</th></tr></thead><tbody>${tx.map(t=>{const bot=botProfiles.find(x=>normalizePhone(x.phone)===normalizePhone(t.phone));const a=accounts.find(x=>normalizePhone(x.phone)===normalizePhone(t.phone))||{};return `<tr><td>${escapeHtml(a.name||bot?.name||t.name||t.phone||"مشتری")}${t._bot?` <small class="muted">· ربات دمو</small>`:""}<br><small>${escapeHtml(t.phone||"")}</small></td><td>${t.type==="credit"?"واریز آزمایشی":t.type==="debit"?"برداشت آزمایشی":escapeHtml(t.typeLabel||"رویداد کیف پول دمو")}</td><td>${money(t.amount||0)}</td><td>${t._bot||t.simulated||t.bot?"دمو · بدون پول واقعی":t.status==="paid"?"موفق آزمایشی":"ثبت‌شده"}</td><td>${escapeHtml(t.paymentReference||t.reference||t.cycleId||"—")}</td><td>${new Date(Number(t.time||t.createdAt)||Date.now()).toLocaleString("fa-IR")}</td></tr>`}).join("")||'<tr><td colspan="6" class="empty-admin">تراکنشی ثبت نشده است.</td></tr>'}</tbody></table></div></div>`;
}
$("#adminContent").addEventListener("click",e=>{
 const clear=e.target.closest("#clearWalletHistory");
 if(!clear)return;
 if(!confirm("تمام تاریخچه تراکنش‌های کیف پول مشتریان و ربات‌های آزمایشی حذف شود؟ موجودی فعلی حفظ خواهد شد."))return;
 const opening=(()=>{try{return JSON.parse(localStorage.getItem("novin_wallet_opening_balances")||"{}")}catch{return {}}})();
 const allPhones=new Set([...accounts.map(a=>a.phone),...walletTransactions.map(t=>t.phone)].filter(Boolean));
 allPhones.forEach(phone=>{const key=normalizePhone(phone);opening[key]=walletBalance(phone);});
 localStorage.setItem("novin_wallet_opening_balances",JSON.stringify(opening));
 walletTransactions=[];
 try{const d=JSON.parse(localStorage.getItem("novin_bot_data")||"{}");d.walletTransactions=[];d.walletHistoryClearedAt=Date.now();localStorage.setItem("novin_bot_data",JSON.stringify(d));}catch{}
 save();renderAdmin("wallets");toast("تاریخچه تراکنش‌ها حذف شد؛ موجودی کیف پول‌ها حفظ شد.");
});

function reportsAdminHtml(){
 const safeOrders=Array.isArray(orders)?orders.filter(o=>o&&typeof o==='object'):[];
 const safeProducts=Array.isArray(products)?products.filter(p=>p&&typeof p==='object'):[];
 const valid=safeOrders.filter(o=>!['cancel','pending'].includes(o.status));
 const revenue=valid.reduce((sum,o)=>sum+Math.max(0,Number(o.total||o.amount)||0),0);
 const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(6-i));const next=new Date(d);next.setDate(next.getDate()+1);const os=valid.filter(o=>Number(o.createdAt)>=d.getTime()&&Number(o.createdAt)<next.getTime());return {name:d.toLocaleDateString('fa-IR',{weekday:'short'}),value:os.reduce((n,o)=>n+Math.max(0,Number(o.total||o.amount)||0),0),count:os.length,amounts:os.map(o=>Math.max(0,Number(o.total||o.amount)||0))};});
 const statusNames={pending:'در انتظار',paid:'پرداخت‌شده',processing:'آماده‌سازی',sent:'ارسال‌شده',delivered:'تحویل‌شده',completed:'تکمیل‌شده',cancel:'لغوشده'};
 const statuses=Object.keys(statusNames).map(key=>({name:statusNames[key],value:safeOrders.filter(o=>o.status===key).length}));
 const categoryData=[...new Set(safeProducts.map(p=>p.category||'سایر'))].map(name=>({name,value:safeProducts.filter(p=>(p.category||'سایر')===name).reduce((n,p)=>n+Math.max(0,Number(p.stock)||0),0)})).sort((a,b)=>b.value-a.value).slice(0,7);
 const sold={};valid.forEach(o=>(Array.isArray(o.items)?o.items:[]).filter(i=>i&&typeof i==='object').forEach(i=>{const name=i.name||productById(i.id)?.name||'محصول حذف‌شده';sold[name]=(sold[name]||0)+Math.max(1,Number(i.qty||i.quantity)||1)}));
 const topSold=Object.entries(sold).map(([name,value])=>({name,value})).sort((a,b)=>b.value-a.value).slice(0,7);
 const low=safeProducts.filter(p=>Number(p.stock||0)<=Number(p.minStock??5)).sort((a,b)=>Number(a.stock)-Number(b.stock)).slice(0,7).map(p=>({name:p.name||'محصول',value:Math.max(0,Number(p.stock)||0),limit:Number(p.minStock??5)}));
 const maxDay=Math.max(1,...days.map(d=>d.value));
 const bars=days.map(d=>`<div class="novin-vbar-item"><b>${money(d.value)}</b><div class="novin-vbar-track"><i style="height:${Math.max(d.value?4:0,d.value/maxDay*100)}%"></i></div><span>${escapeHtml(d.name)}</span></div>`).join('');
 const linePoints=days.map((d,i)=>`${24+i* (252/6)},${105-(d.value/maxDay)*78}`).join(' ');
 const lineDots=days.map((d,i)=>`<circle cx="${24+i*42}" cy="${105-(d.value/maxDay)*78}" r="3.5"><title>${escapeHtml(d.name)}: ${money(d.value)}</title></circle>`).join('');
 const lineLabels=days.map((d,i)=>`<span>${escapeHtml(d.name)}</span>`).join('');
 // Candle-style visualization is derived from daily order values, not financial-market OHLC data.
 let prior=days[0]?.value||0;const candleMax=Math.max(1,...days.flatMap(d=>[d.value,...d.amounts]));
 const candles=days.map((d,i)=>{const open=prior,close=d.value,high=Math.max(open,close,...d.amounts),lowv=Math.min(open,close,...(d.amounts.length?d.amounts:[0]));prior=close;const y=v=>Math.max(5,Math.min(105,105-v/candleMax*90));const top=Math.min(y(open),y(close)),height=Math.max(3,Math.abs(y(open)-y(close)));return `<div class="novin-candle-item"><div class="novin-candle-wick" style="top:${y(high)}px;height:${Math.max(3,y(lowv)-y(high))}px"></div><div class="novin-candle-body ${close>=open?'up':'down'}" style="top:${top}px;height:${height}px" title="باز: ${money(open)}؛ بسته: ${money(close)}؛ سقف: ${money(high)}؛ کف: ${money(lowv)}"></div><span>${escapeHtml(d.name)}</span></div>`}).join('');
 const statusTotal=Math.max(1,statuses.reduce((n,s)=>n+s.value,0));let cursor=0;const palette=['#3b82f6','#10b981','#f59e0b','#8b5cf6','#06b6d4','#ef4444','#64748b'];const stops=statuses.map((s,i)=>{const start=cursor;cursor+=s.value/statusTotal*100;return `${palette[i%palette.length]} ${start}% ${cursor}%`}).join(',');
 const statusLegend=statuses.filter(s=>s.value>0).map(s=>{const i=statuses.indexOf(s);return `<div class="novin-legend-row"><i style="background:${palette[i%palette.length]}"></i><span>${escapeHtml(s.name)}</span><b>${digits(s.value)}</b></div>`}).join('')||'<p class="muted">هنوز سفارشی ثبت نشده است.</p>';
 const horizontal=(items,suffix)=>items.length?`<div class="novin-hbars">${items.map(x=>{const max=Math.max(1,...items.map(y=>y.value));return `<div class="novin-hbar-row"><span title="${escapeHtml(x.name)}">${escapeHtml(x.name)}</span><div><i style="width:${Math.max(x.value?3:0,x.value/max*100)}%"></i></div><b>${digits(x.value)} ${suffix}</b></div>`}).join('')}</div>`:'<p class="muted">داده‌ای برای نمایش وجود ندارد.</p>';
 return `<div class="stats-grid"><div class="stat-card"><div class="stat-top">فروش ثبت‌شده</div><div class="stat-value">${money(revenue)}</div><div class="stat-note">سفارش‌های غیرلغوشده و غیرمنتظر پرداخت؛ شامل داده‌های دمو در صورت وجود</div></div><div class="stat-card"><div class="stat-top">میانگین سفارش</div><div class="stat-value">${money(valid.length?Math.round(revenue/valid.length):0)}</div><div class="stat-note">بر اساس ${digits(valid.length)} سفارش</div></div><div class="stat-card"><div class="stat-top">کل موجودی</div><div class="stat-value">${digits(safeProducts.reduce((n,p)=>n+Math.max(0,Number(p.stock)||0),0))}</div><div class="stat-note">تعداد واحدها</div></div><div class="stat-card"><div class="stat-top">کم‌موجود / ناموجود</div><div class="stat-value">${digits(low.length)}</div><div class="stat-note">محصولات نیازمند بررسی</div></div></div>
 <style>.report-chart-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,360px),1fr));gap:16px;margin:16px 0}.report-chart-card{min-width:0;overflow:hidden}.novin-vbars{height:230px;display:flex;align-items:stretch;gap:10px;padding:12px 4px 0;direction:ltr}.novin-vbar-item{flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;gap:6px;font-size:11px}.novin-vbar-item>b{font-size:10px;direction:rtl;white-space:nowrap}.novin-vbar-track{height:160px;width:min(28px,70%);background:var(--border-color,#e5e7eb);border-radius:7px;display:flex;align-items:flex-end;overflow:hidden}.novin-vbar-track i{display:block;width:100%;background:linear-gradient(180deg,#60a5fa,#2563eb);border-radius:7px 7px 0 0}.novin-vbar-item>span{direction:rtl}.novin-line-svg{width:100%;height:150px;display:block;overflow:visible}.novin-line-svg polyline{fill:none;stroke:#0d9488;stroke-width:3;stroke-linejoin:round;stroke-linecap:round}.novin-line-svg circle{fill:#0d9488;stroke:#fff;stroke-width:1.5}.novin-line-labels{display:flex;justify-content:space-between;direction:rtl;font-size:11px}.novin-candles{height:175px;display:flex;gap:12px;justify-content:space-around;direction:ltr;padding:8px 4px 0}.novin-candle-item{height:150px;position:relative;flex:1;max-width:48px}.novin-candle-wick{position:absolute;left:50%;width:2px;background:#64748b;transform:translateX(-50%)}.novin-candle-body{position:absolute;left:50%;width:13px;transform:translateX(-50%);border-radius:2px}.novin-candle-body.up{background:#10b981}.novin-candle-body.down{background:#ef4444}.novin-candle-item>span{position:absolute;bottom:-18px;left:50%;transform:translateX(-50%);font-size:10px;direction:rtl}.novin-donut-wrap{display:flex;align-items:center;gap:20px;justify-content:center;flex-wrap:wrap;padding:14px}.novin-donut{width:150px;height:150px;border-radius:50%;background:conic-gradient(${stops});position:relative;flex:none}.novin-donut:after{content:'${digits(statusTotal)}';position:absolute;inset:29px;border-radius:50%;background:var(--card-bg,#fff);display:grid;place-items:center;font-size:20px;font-weight:700}.novin-legend{min-width:145px;display:grid;gap:8px}.novin-legend-row{display:flex;align-items:center;gap:7px;font-size:12px}.novin-legend-row i{width:10px;height:10px;border-radius:3px;flex:none}.novin-legend-row b{margin-inline-start:auto}.novin-hbars{display:grid;gap:12px}.novin-hbar-row{display:grid;grid-template-columns:minmax(80px,1fr) minmax(70px,2fr) auto;align-items:center;gap:8px;font-size:12px}.novin-hbar-row>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.novin-hbar-row>div{height:12px;background:var(--border-color,#e5e7eb);border-radius:8px;overflow:hidden}.novin-hbar-row i{display:block;height:100%;background:linear-gradient(90deg,#a78bfa,#7c3aed);border-radius:8px}</style>
 <div class="report-chart-grid">
 <div class="panel-card report-chart-card"><div class="panel-head"><h3>۱. نمودار ستونی فروش روزانه</h3><span class="eyebrow">۷ روز اخیر</span></div><div class="novin-vbars">${bars}</div></div>
 <div class="panel-card report-chart-card"><div class="panel-head"><h3>۲. نمودار خطی روند فروش</h3><span class="eyebrow">۷ روز اخیر</span></div><svg class="novin-line-svg" viewBox="0 0 276 125" role="img" aria-label="روند فروش هفت روز اخیر"><line x1="20" y1="105" x2="270" y2="105" stroke="currentColor" opacity=".15"/><line x1="20" y1="65" x2="270" y2="65" stroke="currentColor" opacity=".1"/><line x1="20" y1="25" x2="270" y2="25" stroke="currentColor" opacity=".1"/><polyline points="${linePoints}"/>${lineDots}</svg><div class="novin-line-labels">${lineLabels}</div></div>
 <div class="panel-card report-chart-card"><div class="panel-head"><h3>۳. نمودار کندلی سفارش‌ها</h3><span class="eyebrow">نمایش مشتق‌شده</span></div><div class="novin-candles">${candles}</div><p class="muted" style="margin-top:24px">کندل‌ها از مبلغ سفارش‌های هر روز ساخته شده‌اند و داده بازار مالی واقعی نیستند.</p></div>
 <div class="panel-card report-chart-card"><div class="panel-head"><h3>۴. نمودار حلقه‌ای وضعیت سفارش‌ها</h3><span class="eyebrow">همه سفارش‌ها</span></div><div class="novin-donut-wrap"><div class="novin-donut" role="img" aria-label="توزیع وضعیت سفارش‌ها"></div><div class="novin-legend">${statusLegend}</div></div></div>
 <div class="panel-card report-chart-card"><div class="panel-head"><h3>۵. نمودار افقی پرفروش‌ترین محصولات</h3><span class="eyebrow">تعداد اقلام</span></div>${horizontal(topSold,'عدد')}</div>
 </div>
 <div class="panel-card"><div class="panel-head"><h3>بررسی کمبود موجودی</h3></div>${horizontal(low.map(x=>({name:x.name,value:x.value})),'عدد')}<p class="muted">محصولاتی که موجودی آن‌ها به حد هشدار رسیده است. این فهرست مکمل نمودارهای بالا است.</p></div>
 <div class="panel-card"><div class="panel-head"><h3>خروجی اطلاعات</h3></div><p>گزارش‌ها بر اساس داده‌های فعلی مرورگر ساخته شده‌اند؛ سفارش‌های آزمایشی را با فروش واقعی اشتباه نگیرید.</p><button class="outline" id="exportProducts" type="button">دریافت فهرست محصولات</button> <button class="outline" id="exportOrders" type="button">دریافت فهرست سفارش‌ها</button> <button class="outline" data-panel-link="inventory" type="button">مدیریت انبار ←</button></div>`;
}
function shippingAdminHtml(){return `<div class="stats-grid"><div class="stat-card"><div class="stat-top">شرکت‌های فعال <span class="stat-icon">🚚</span></div><div class="stat-value">${digits(shippingCompanies.filter(c=>c.active).length)}</div><div class="stat-note">روش‌های قابل انتخاب در ثبت سفارش</div></div><div class="stat-card"><div class="stat-top">سفارش‌های ارسال‌شده <span class="stat-icon">📦</span></div><div class="stat-value">${digits(orders.filter(o=>o.status==="sent"||o.status==="delivered").length)}</div><div class="stat-note">سفارش‌های دارای مرحله ارسال</div></div></div><div class="panel-card"><div class="panel-head"><h3>مدیریت شرکت‌های ارسال</h3><button class="primary small" id="addShippingCompany">＋ افزودن شرکت</button></div><p class="muted">هزینه‌ها و زمان‌های زیر برای نسخه آزمایشی هستند و به سرویس پستی واقعی متصل نیستند.</p><div class="table-wrap"><table><thead><tr><th>شرکت</th><th>هزینه (تومان)</th><th>زمان تقریبی</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${shippingCompanies.map(c=>`<tr><td>${escapeHtml(c.name)}</td><td>${money(c.fee)}</td><td>${escapeHtml(c.eta)}</td><td>${c.active?'<span class="status paid">فعال</span>':'<span class="status cancel">غیرفعال</span>'}</td><td><button class="table-action" data-edit-shipping="${escapeHtml(c.id)}">ویرایش</button> <button class="table-action" data-toggle-shipping="${escapeHtml(c.id)}">${c.active?'غیرفعال':'فعال'}</button> <button class="danger-btn" data-delete-shipping="${escapeHtml(c.id)}">حذف</button></td></tr>`).join('')||'<tr><td colspan="5">شرکتی ثبت نشده است.</td></tr>'}</tbody></table></div></div><div class="panel-card"><h3>راهنمای نشانی و مرسوله</h3><p class="muted">نشانی مشتری در فرم ثبت سفارش ذخیره می‌شود و مدیر آن را داخل جزئیات سفارش، در بخش «اطلاعات ارسال» مشاهده می‌کند. پس از تحویل مرسوله به شرکت ارسال، کد رهگیری را در همان بخش ثبت کنید.</p><button class="outline" id="openOrdersFromShipping">رفتن به سفارش‌ها</button></div>`}
function postAutomationAdminHtml(){
 const status={configured:false,dispatchConfigured:false,webhookConfigured:false,message:'وضعیت اتصال پس از بارگذاری بررسی می‌شود…'};
 const incidents=[];
 const eligible=orders.filter(o=>['paid','processing'].includes(o.status)&&!(o.postDispatch&&o.postDispatch.accepted));
 return `<div class="panel-card"><div class="panel-head"><h3>اتصال عملیاتی شرکت ملی پست</h3><span class="status ${status.dispatchConfigured?'paid':'wait'}">${status.dispatchConfigured?'سرویس ثبت مرسوله پیکربندی شده':'اتصال ارسال خودکار فعال نیست'}</span></div><p>${escapeHtml(status.message||'')}</p><p class="muted">این پنل تنها پس از تنظیم دسترسی قراردادی و آداپتور مورد تأیید می‌تواند مرسوله واقعی ثبت کند. ایجاد سفارش در این صفحه به‌تنهایی به معنی تحویل فیزیکی بسته به پست نیست.</p><div class="stats-grid"><div class="stat-card"><div class="stat-top">آماده بررسی ارسال <span class="stat-icon">📦</span></div><div class="stat-value">${digits(eligible.length)}</div><div class="stat-note">سفارش پرداخت‌شده/در حال آماده‌سازی</div></div><div class="stat-card"><div class="stat-top">هشدارهای دریافتی <span class="stat-icon">⚠️</span></div><div class="stat-value">${digits(incidents.filter(x=>!x.acknowledged).length)}</div><div class="stat-note">رویدادهای تأییدنشده توسط مدیر</div></div><div class="stat-card"><div class="stat-top">مرسوله‌های ثبت‌شده از API <span class="stat-icon">🔗</span></div><div class="stat-value">${digits(orders.filter(o=>o.postDispatch?.accepted).length)}</div><div class="stat-note">بر اساس پاسخ صریح سرویس متصل</div></div></div></div>
 <div class="panel-card"><div class="panel-head"><h3>صف ارسال خودکار</h3><button class="outline small" id="refreshPostAutomation">↻ تازه‌سازی</button></div><p class="muted">پیش از ارسال، نشانی کامل، کد پستی و شماره تماس را کنترل کن. ارسال واقعی فقط وقتی انجام می‌شود که سرویس مجاز و معتبر در سرور تنظیم شده باشد.</p><div class="delivery-order-list">${eligible.map(o=>`<article class="delivery-order-card"><div class="delivery-order-top"><div><b>سفارش #${escapeHtml(o.number||o.id)}</b><small>${escapeHtml(o.customer?.name||'مشتری')} · ${escapeHtml(o.customer?.phone||'تلفن ثبت نشده')}</small></div><strong>${money(o.total||0)}</strong></div><p><b>نشانی:</b> ${escapeHtml(o.customer?.address||o.address||'نشانی ثبت نشده')} · <b>کدپستی:</b> ${escapeHtml(o.customer?.postal||o.customer?.postalCode||o.postalCode||'ثبت نشده')}</p><p><b>اقلام:</b> ${(o.items||[]).map(i=>`${escapeHtml(i.name||'کالا')} × ${digits(i.qty||1)}`).join('، ')||'ثبت نشده'}</p><div class="modal-actions"><button type="button" class="primary small" data-post-dispatch="${escapeHtml(o.id)}" >ثبت مرسوله از طریق سرویس متصل</button><button type="button" class="outline small" data-order="${escapeHtml(o.id)}">جزئیات سفارش</button></div>${o.postDispatch?`<p class="muted">آخرین نتیجه: ${escapeHtml(o.postDispatch.message||o.postDispatch.status||'ثبت شده')} ${o.postDispatch.trackingNumber?` · کد رهگیری ${escapeHtml(o.postDispatch.trackingNumber)}`:''}</p>`:''}</article>`).join('')||'<div class="empty-admin">سفارش پرداخت‌شده‌ای در صف ارسال نیست.</div>'}</div></div>
 <div class="panel-card"><div class="panel-head"><h3>مرکز هشدارهای شرکت پست</h3><button class="outline small" id="refreshPostIncidents">↻ تازه‌سازی هشدارها</button></div><p class="muted">این فهرست فقط رویدادهایی را نشان می‌دهد که سرویس متصل یا webhook پیکربندی‌شده به سرور گزارش کرده باشد؛ بدون این اتصال، رویداد واقعی خودکار دریافت نمی‌شود.</p><div class="post-incident-list">${incidents.map(x=>`<article class="parcel-result ${x.severity==='critical'?'is-warning':''}"><div class="panel-head"><b>${escapeHtml(x.title||x.status||'رویداد مرسوله')}</b><span class="status ${x.acknowledged?'paid':'wait'}">${x.acknowledged?'بررسی‌شده':'نیازمند بررسی'}</span></div><p>${escapeHtml(x.message||x.description||'بدون توضیح')}</p><p class="muted">کد رهگیری: <span dir="ltr">${escapeHtml(x.trackingNumber||'ثبت نشده')}</span> · ${escapeHtml(x.createdAt||'')}</p></article>`).join('')||'<p class="muted">هشداری از سرویس متصل دریافت نشده است.</p>'}</div></div>
 <div class="panel-card"><h3>قابلیت‌های آماده برای اتصال</h3><div class="feature-grid"><div class="feature-item"><b>📄 تولید برچسب/بارکد</b><p>پس از پشتیبانی سرویس قراردادی؛ برچسب واقعی باید از سرویس صادر شود.</p></div><div class="feature-item"><b>🚚 درخواست جمع‌آوری</b><p>فقط اگر قرارداد یا ارائه‌دهنده انتخابی این عملیات را پشتیبانی کند.</p></div><div class="feature-item"><b>⏱️ پایش تأخیر</b><p>با رویدادهای API یا webhook و سیاست آستانه تأخیر قابل فعال‌سازی است.</p></div><div class="feature-item"><b>📷 مدارک بسته</b><p>عکس قبل از ارسال و گزارش آسیب در بخش تحویل کالا نگهداری می‌شود.</p></div></div></div>`;
}

async function loadPostAutomationPanelData(){
 const statusRoot=$('#adminContent .panel-card .panel-head h3')?.closest('.panel-card');
 try{const [sr,ir]=await Promise.all([fetch('/api/post/config-status',{cache:'no-store'}),fetch('/api/post/incidents',{cache:'no-store'})]);const st=await sr.json();const id=await ir.json();if(currentAdminPanel!=='postAutomation')return;
 const status=statusRoot?.querySelector('.status');if(status){status.textContent=st.dispatchConfigured?'سرویس ثبت مرسوله پیکربندی شده':'اتصال ارسال خودکار فعال نیست';status.className='status '+(st.dispatchConfigured?'paid':'wait')}
 const message=statusRoot?.querySelector('p');if(message)message.textContent=st.message||'';
 $$('#adminContent [data-post-dispatch]').forEach(b=>{b.disabled=!st.dispatchConfigured;b.title=st.dispatchConfigured?'ارسال درخواست به آداپتور متصل':'ابتدا دسترسی API مجاز را در تنظیمات سرور پیکربندی کن'});
 const stats=$$('#adminContent .stats-grid .stat-card .stat-value');if(stats[1])stats[1].textContent=digits((id.items||[]).filter(x=>!x.acknowledged).length);
 const root=$('#adminContent .post-incident-list');if(root){root.innerHTML=(id.items||[]).map(x=>`<article class="parcel-result ${x.severity==='critical'?'is-warning':''}"><div class="panel-head"><b>${escapeHtml(x.title||x.status||'رویداد مرسوله')}</b><span class="status ${x.acknowledged?'paid':'wait'}">${x.acknowledged?'بررسی‌شده':'نیازمند بررسی'}</span></div><p>${escapeHtml(x.message||x.description||'بدون توضیح')}</p><p class="muted">کد رهگیری: <span dir="ltr">${escapeHtml(x.trackingNumber||'ثبت نشده')}</span> · ${escapeHtml(x.createdAt||'')}</p>${!x.acknowledged?`<button class="outline small" data-post-incident-ack="${escapeHtml(x.id)}">علامت‌گذاری به‌عنوان بررسی‌شده</button>`:''}</article>`).join('')||'<p class="muted">هشداری از سرویس متصل دریافت نشده است.</p>'}
 }catch{const msg=$('#adminContent .panel-card .panel-head h3')?.closest('.panel-card')?.querySelector('p');if(msg)msg.textContent='وضعیت اتصال سرور قابل دریافت نیست؛ سرور را بررسی کن.'}
}

function shippingCompanyForm(company=null){openModal(`<div class="modal-title-row"><h2>${company?'ویرایش شرکت ارسال':'افزودن شرکت ارسال'}</h2><button class="close-btn" data-modal-close>×</button></div><form id="shippingCompanyForm"><div class="form-grid"><div class="field full-field"><label>نام شرکت</label><input name="name" required value="${escapeHtml(company?.name||'')}"></div><div class="field"><label>هزینه ارسال (تومان)</label><input name="fee" type="number" min="0" required value="${company?.fee??150000}"></div><div class="field"><label>زمان تقریبی</label><input name="eta" required value="${escapeHtml(company?.eta||'۲ تا ۵ روز کاری')}"></div><div class="field"><label><input type="checkbox" name="active" ${company?.active===false?'':'checked'}> فعال باشد</label></div></div><div class="modal-actions"><button class="primary">ذخیره</button><button type="button" class="outline" data-modal-close>انصراف</button></div></form>`);$('#shippingCompanyForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),item={id:company?.id||`ship-${Date.now()}`,name:String(f.get('name')).trim(),fee:Number(f.get('fee')),eta:String(f.get('eta')).trim(),active:f.get('active')==='on'};if(!item.name||item.fee<0)return toast('اطلاعات شرکت را بررسی کنید.');if(company)shippingCompanies=shippingCompanies.map(x=>x.id===company.id?item:x);else shippingCompanies.push(item);save();closeModal();renderAdmin('shipping');toast('اطلاعات شرکت ارسال ذخیره شد.');};}
function printStandaloneReceipt(o){const w=window.open("","_blank","width=800,height=700");if(!w)return toast("اجازه بازشدن پنجره چاپ را بده.");w.document.write(`<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><title>رسید ${escapeHtml(o.receipt?.number||o.number)}</title><style>body{font-family:Tahoma,Arial;padding:32px;color:#20283b;max-width:760px;margin:auto}h1{font-size:24px}.tag{padding:8px 12px;background:#eefbf5;border-radius:8px;display:inline-block}hr{border:0;border-top:1px solid #ddd;margin:20px 0}.row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #eee}.note{color:#6c7485;font-size:12px;line-height:2;margin-top:24px}</style><h1>رسید پرداخت آزمایشی نوین‌شاپ</h1><span class="tag">${o.status==="paid"?"موفق (آزمایشی)":"در انتظار پرداخت"}</span><hr><div class="row"><span>شماره رسید</span><b>${escapeHtml(o.receipt?.number||("NS-"+o.number))}</b></div><div class="row"><span>شماره سفارش/تراکنش</span><b>${escapeHtml(o.number)}</b></div><div class="row"><span>تاریخ</span><b>${new Date(o.receipt?.issuedAt||Date.now()).toLocaleString("fa-IR")}</b></div><div class="row"><span>پرداخت‌کننده</span><b>${escapeHtml(o.customer?.name||"مشتری")}</b></div><div class="row"><span>درگاه</span><b>${escapeHtml(o.paymentGateway||"درگاه آزمایشی")}</b></div><div class="row"><span>شماره پیگیری</span><b>${escapeHtml(o.paymentReference||"ثبت نشده")}</b></div><div class="row"><span>مبلغ</span><b>${money(o.total||o.amount||0)}</b></div><p class="note">این رسید برای نسخه نمایشی نوین‌شاپ صادر شده و مدرک دریافت وجه واقعی یا سند بانکی نیست.</p><script>window.onload=()=>window.print()<\/script></html>`);w.document.close();}
function printInvoice(id){const o=orders.find(x=>String(x.id)===String(id)||String(x.number)===String(id));if(!o)return toast("سفارش یا رسید پیدا نشد؛ صفحه را تازه‌سازی کن.");const w=window.open('','_blank','width=800,height=700');if(!w)return toast('اجازه بازشدن پنجره چاپ را بده.');w.document.write(`<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><title>فاکتور ${escapeHtml(o.number)}</title><style>body{font-family:Tahoma,Arial;padding:32px;color:#222}h1{font-size:22px}table{width:100%;border-collapse:collapse;margin-top:24px}td,th{border:1px solid #ddd;padding:10px;text-align:right}.total{font-size:20px;font-weight:bold;margin-top:24px}</style><h1>رسید پرداخت آزمایشی نوین‌شاپ</h1><p>شماره رسید: ${escapeHtml(o.receipt?.number||("NS-"+o.number))} · شماره سفارش: #${escapeHtml(o.number)}</p><p>تاریخ سفارش: ${new Date(o.createdAt).toLocaleString('fa-IR')} · تاریخ صدور رسید: ${new Date(o.receipt?.issuedAt||Date.now()).toLocaleString('fa-IR')}</p><p>وضعیت پرداخت: ${o.status==="paid"?"موفق (آزمایشی)":o.status==="pending"?"در انتظار پرداخت/پرداخت هنگام تحویل":"ناموفق/لغوشده"} · درگاه: ${escapeHtml(o.paymentGateway||"درگاه آزمایشی")}</p><p>شماره پیگیری: ${escapeHtml(o.paymentReference||"ثبت نشده")}</p><p>گیرنده: ${escapeHtml(o.customer.name)} · ${escapeHtml(o.customer.phone)}</p><p>نشانی ارسال: ${escapeHtml(o.customer.address)} ${escapeHtml(o.customer.city||'')} · کد پستی ${escapeHtml(o.customer.postal||'ثبت نشده')}</p><table><thead><tr><th>کالا</th><th>تعداد</th><th>قیمت واحد</th><th>جمع</th></tr></thead><tbody>${(Array.isArray(o.items)?o.items:[]).map(i=>`<tr><td>${escapeHtml(i.name||"کالا")}</td><td>${digits(i.qty||0)}</td><td>${money(i.price||0)}</td><td>${money((i.price||0)*(i.qty||0))}</td></tr>`).join('')}</tbody></table><p>شرکت ارسال: ${escapeHtml(o.shippingProvider||'تعیین نشده')} · کد رهگیری: ${escapeHtml(o.trackingCode||'ثبت نشده')}</p><p class="total">مبلغ نهایی: ${money(o.total)}</p><script>window.onload=()=>window.print()<\/script></html>`);w.document.close();}
function insuranceAdminHtml(){
 const rows=insuranceRecords.slice().sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0));
 const orderItems=orders.flatMap(o=>(o.items||[]).filter(i=>i.insurance||i.insurancePlan||i.insured).map(i=>({order:o,item:i}))) ;
 return `<div class="stats-grid"><div class="stat-card"><div class="stat-top">پرونده‌های بیمه <span class="stat-icon">🛡</span></div><div class="stat-value">${digits(rows.length+orderItems.length)}</div><div class="stat-note">درخواست‌ها و بیمه‌های ثبت‌شده نمایشی · شامل موارد در انتظار تأیید</div></div><div class="stat-card"><div class="stat-top">شرکت‌های بیمه فعال <span class="stat-icon">✓</span></div><div class="stat-value">${digits(insuranceCompanies.filter(c=>c.active).length)}</div><div class="stat-note">شرکت‌های قابل انتخاب در ثبت پرونده</div></div></div><div class="panel-card"><div class="panel-head"><h3>شرکت‌های بیمه</h3><button class="primary small" id="addInsuranceCompany">＋ شرکت جدید</button></div><p class="muted">این شرکت‌ها و طرح‌ها در نسخه نمایشی‌اند و به شرکت بیمه واقعی متصل نیستند.</p><div class="table-wrap"><table><thead><tr><th>شرکت</th><th>توضیحات</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${insuranceCompanies.map(c=>`<tr><td>${escapeHtml(c.name)}</td><td>${escapeHtml(c.description||'—')}</td><td>${c.active?'<span class="status paid">فعال</span>':'<span class="status cancel">غیرفعال</span>'}</td><td><button class="table-action" data-insurance-toggle="${escapeHtml(c.id)}">${c.active?'غیرفعال':'فعال'}</button> <button class="danger-btn" data-insurance-delete="${escapeHtml(c.id)}">حذف</button></td></tr>`).join('')||'<tr><td colspan="4">شرکتی ثبت نشده است.</td></tr>'}</tbody></table></div></div><div class="panel-card"><div class="panel-head"><h3>تخصیص بیمه به محصولات</h3><span class="muted">از دکمه ویرایش در مدیریت محصولات، شرکت و قیمت بیمه هر کالا را تعیین کن.</span></div><div class="table-wrap"><table><thead><tr><th>محصول</th><th>شرکت‌های بیمه</th><th>قیمت بیمه</th><th>عملیات</th></tr></thead><tbody>${products.map(p=>{const opts=(p.insuranceOptions||[]).filter(o=>insuranceCompanies.some(c=>c.id===o.companyId&&c.active));return `<tr><td>${escapeHtml(p.name)}</td><td>${opts.length?opts.map(o=>escapeHtml(o.companyName||insuranceCompanies.find(c=>c.id===o.companyId)?.name||'شرکت')).join('، '):p.insuranceEnabled?'بیمه قدیمی':'بدون بیمه'}</td><td>${opts.length?opts.map(o=>money(o.price)).join(' / '):p.insuranceEnabled?money(p.insurancePrice||0):'—'}</td><td><button class="table-action" data-edit="${p.id}">تنظیم بیمه کالا</button></td></tr>`}).join('')}</tbody></table></div></div><div class="panel-card"><div class="panel-head"><h3>پرونده‌های بیمه مشتریان</h3><span class="muted">${digits(rows.length)} درخواست</span></div><div class="table-wrap"><table><thead><tr><th>مشتری</th><th>محصول</th><th>شرکت / طرح</th><th>شماره سفارش</th><th>وضعیت</th><th>تاریخ</th><th>عملیات</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHtml(r.customerName||'مشتری')}<br><small>${escapeHtml(r.phone||'')}</small></td><td>${escapeHtml(r.productName||'محصول')}</td><td>${escapeHtml(r.companyName||r.plan||'در انتظار بررسی')}</td><td>${escapeHtml(r.orderNumber||'—')}</td><td><span class="status ${r.status==='فعال'?'paid':'wait'}">${escapeHtml(r.status||'در انتظار بررسی')}</span></td><td>${r.createdAt?new Date(r.createdAt).toLocaleString('fa-IR'):'—'}</td><td>${r.decision==='pending'||!r.decision?`<button type="button" class="table-action" data-insurance-decision="approve" data-insurance-id="${escapeHtml(r.id)}">تأیید بیمه</button> <button type="button" class="danger-btn" data-insurance-decision="reject" data-insurance-id="${escapeHtml(r.id)}">رد بیمه</button>`:`<span class="muted">تصمیم ثبت شده</span> <button type="button" class="table-action" data-insurance-status="${escapeHtml(r.id)}">تغییر وضعیت</button>`}</td></tr>`).join('')||'<tr><td colspan="7" class="empty-admin">پرونده بیمه‌ای ثبت نشده است.</td></tr>'}</tbody></table></div></div><div class="panel-card"><h3>بیمه‌های درج‌شده در سفارش‌ها</h3><div class="table-wrap"><table><thead><tr><th>مشتری</th><th>محصول</th><th>سفارش</th><th>طرح</th><th>وضعیت</th></tr></thead><tbody>${orderItems.map(x=>`<tr><td>${escapeHtml(x.order.customer?.name||'مشتری')}</td><td>${escapeHtml(x.item.name||'محصول')}</td><td>#${escapeHtml(x.order.number)}</td><td>${escapeHtml(x.item.insurancePlan||'طرح ثبت‌شده')}</td><td>${escapeHtml(x.item.insuranceStatus||'ثبت‌شده')}</td></tr>`).join('')||'<tr><td colspan="5">بیمه‌ای روی اقلام سفارش ثبت نشده است.</td></tr>'}</tbody></table></div></div>`;
}
function pointsAdminHtml(){const phones=[...new Set([...accounts.map(a=>a.phone),...orders.map(o=>o.customer?.phone).filter(Boolean)])];const pointsFor=phone=>orders.filter(o=>normalizePhone(o.customer?.phone)===normalizePhone(phone)&&['paid','processing','sent','delivered','completed'].includes(o.status)).reduce((sum,o)=>sum+Math.floor(Number(o.total||0)/100000),0);return `<div class="panel-card"><div class="panel-head"><h3>امتیازهای باشگاه مشتریان</h3><button class="outline" id="exportCustomerPoints">خروجی CSV</button></div><p class="muted">امتیازها در این نسخه بر اساس هر ۱۰۰ هزار تومان از سفارش‌های پرداخت‌شده محاسبه می‌شوند و ارزش نقدی ندارند.</p><div class="table-wrap"><table><thead><tr><th>مشتری</th><th>شماره حساب</th><th>تعداد سفارش معتبر</th><th>امتیاز</th><th>تاریخ آخرین سفارش</th></tr></thead><tbody>${phones.map(phone=>{const a=accounts.find(x=>normalizePhone(x.phone)===normalizePhone(phone))||{},os=orders.filter(o=>normalizePhone(o.customer?.phone)===normalizePhone(phone)&&['paid','processing','sent','delivered','completed'].includes(o.status));return `<tr><td>${escapeHtml(a.name||os[0]?.customer?.name||'مشتری')}</td><td>${escapeHtml(phone)}</td><td>${digits(os.length)}</td><td><b>${digits(pointsFor(phone))}</b></td><td>${os.length?new Date(Math.max(...os.map(o=>o.createdAt||0))).toLocaleDateString('fa-IR'):'—'}</td></tr>`}).join('')||'<tr><td colspan="5">هنوز مشتری‌ای ثبت نشده است.</td></tr>'}</tbody></table></div></div>`;}
function inventoryAdminHtml(){const low=products.filter(p=>Number(p.stock||0)<=Number(p.minStock??5));const total=products.reduce((n,p)=>n+Math.max(0,Number(p.stock)||0),0);return `<div class="stats-grid"><div class="stat-card"><div class="stat-top">کل موجودی انبار</div><div class="stat-value">${digits(total)}</div><div class="stat-note">مجموع تعداد واحدها</div></div><div class="stat-card"><div class="stat-top">نیازمند تأمین</div><div class="stat-value">${digits(low.length)}</div><div class="stat-note">بر اساس حد هشدار هر محصول</div></div><div class="stat-card"><div class="stat-top">ناموجود</div><div class="stat-value">${digits(products.filter(p=>Number(p.stock)===0).length)}</div><div class="stat-note">محصول با موجودی صفر</div></div></div>
 <div class="panel-card"><div class="panel-head"><div><h3>افزودن سریع موجودی</h3><p class="muted">محصول را انتخاب کن، تعداد ورودی را وارد کن و با یک دکمه به موجودی فعلی اضافه کن.</p></div><button class="outline" id="exportInventory">خروجی CSV انبار</button></div><form id="quickStockAddForm" class="quick-stock-form"><div class="field"><label for="quickStockProduct">محصول</label><select id="quickStockProduct" name="productId" required><option value="">انتخاب محصول…</option>${products.slice().sort((a,b)=>a.name.localeCompare(b.name,'fa')).map(p=>`<option value="${escapeHtml(p.id)}">${escapeHtml(p.name)} · موجودی: ${digits(p.stock)}</option>`).join('')}</select></div><div class="field"><label for="quickStockQty">تعداد ورودی</label><input id="quickStockQty" name="quantity" type="number" min="1" step="1" value="1" required></div><div class="field"><label for="quickStockNote">یادداشت (اختیاری)</label><input id="quickStockNote" name="note" maxlength="120" placeholder="مثلاً خرید جدید از تأمین‌کننده"></div><button type="submit" class="primary">＋ افزودن به موجودی</button></form><p class="muted" id="quickStockFeedback" aria-live="polite">افزودن موجودی، تعداد فعلی محصول را افزایش می‌دهد و در این مرورگر ذخیره می‌شود.</p></div>
 <div class="panel-card"><div class="panel-head"><div><h3>انبار و اصلاح موجودی</h3><p class="muted">با دکمه‌های +1، +5 و +10 می‌توانی سریع موجودی را افزایش بدهی؛ «اصلاح» برای تعیین عدد دقیق است.</p></div><input id="inventorySearch" aria-label="جست‌وجوی انبار" placeholder="جست‌وجوی محصول یا SKU…"></div><div class="table-wrap"><table><thead><tr><th>محصول</th><th>SKU</th><th>موجودی</th><th>حد هشدار</th><th>وضعیت</th><th>افزودن سریع</th><th>عملیات</th></tr></thead><tbody>${products.slice().sort((a,b)=>Number(a.stock)-Number(b.stock)).map(p=>`<tr data-inventory-row="${escapeHtml((p.name+' '+(p.sku||'')).toLowerCase())}"><td>${escapeHtml(p.name)}</td><td>${escapeHtml(p.sku||'—')}</td><td><b>${digits(p.stock)}</b></td><td>${digits(p.minStock??5)}</td><td>${p.stock===0?'<span class="status cancel">ناموجود</span>':p.stock<=(p.minStock??5)?'<span class="status wait">کم‌موجود</span>':'<span class="status paid">موجود</span>'}</td><td><button class="table-action" data-stock-add="${escapeHtml(p.id)}" data-stock-amount="1">+1</button> <button class="table-action" data-stock-add="${escapeHtml(p.id)}" data-stock-amount="5">+5</button> <button class="table-action" data-stock-add="${escapeHtml(p.id)}" data-stock-amount="10">+10</button></td><td><button class="table-action" data-stock-adjust="${escapeHtml(p.id)}">اصلاح دقیق</button> <button class="table-action" data-edit="${escapeHtml(p.id)}">ویرایش</button></td></tr>`).join('')||'<tr><td colspan="7">محصولی ثبت نشده است.</td></tr>'}</tbody></table></div></div>`}
function loyaltyAdminHtml(){
 const phones=[...new Set([...accounts.map(a=>normalizePhone(a.phone)),...orders.map(o=>normalizePhone(o.customer?.phone)).filter(Boolean),...loyaltyCoupons.map(c=>normalizePhone(c.phone))].filter(Boolean))];
 const validStatus=["paid","processing","sent","delivered","completed"];
 const rows=phones.map(phone=>{const account=accounts.find(a=>normalizePhone(a.phone)===phone)||{},os=orders.filter(o=>normalizePhone(o.customer?.phone)===phone&&validStatus.includes(o.status)&&!['wallet_topup','plus_subscription'].includes(o.type)),cs=loyaltyCoupons.filter(c=>normalizePhone(c.phone)===phone).sort((a,b)=>Number(b.createdAt)-Number(a.createdAt));return `<tr data-loyalty-row><td>${escapeHtml(account.name||os[0]?.customer?.name||cs[0]?.customerName||'مشتری')}</td><td dir="ltr">${escapeHtml(phone)}</td><td>${digits(os.length)}</td><td>${digits(Math.floor(os.length/5))} هدیه واجد شرایط</td><td>${cs.map(c=>`<div class="loyalty-code-line"><b dir="ltr">${escapeHtml(c.code)}</b><small>${digits(c.percent)}٪ · ${c.usedAt?'استفاده‌شده':c.active?'فعال':'غیرفعال'}${c.milestone?` · هدیه خرید ${digits(c.milestone)}`:' · دستی'}</small></div>`).join('')||'—'}</td><td><button class="outline small" data-loyalty-issue="${escapeHtml(phone)}">صدور کد دستی</button> <button class="outline small" data-loyalty-notify="${escapeHtml(phone)}">مشاهده پیام‌ها</button></td></tr>`}).join('');
 return `<div class="stats-grid"><div class="stat-card"><div class="stat-top">مشتریان قابل استعلام</div><div class="stat-value">${digits(phones.length)}</div><div class="stat-note">بر اساس حساب‌ها و سفارش‌های همین مرورگر</div></div><div class="stat-card"><div class="stat-top">کدهای اختصاصی صادرشده</div><div class="stat-value">${digits(loyaltyCoupons.length)}</div><div class="stat-note">شامل هدیه‌های هر ۵ خرید و صدور دستی</div></div><div class="stat-card"><div class="stat-top">کدهای فعال</div><div class="stat-value">${digits(loyaltyCoupons.filter(c=>c.active&&!c.usedAt).length)}</div><div class="stat-note">هر کد به یک شماره حساب متصل است</div></div></div><div class="panel-card"><div class="panel-head"><div><h3>استعلام باشگاه مشتریان</h3><p class="muted">جست‌وجو بر اساس نام، شماره موبایل یا کد تخفیف</p></div></div><div class="field"><label for="loyaltyAdminSearch">جست‌وجوی مشتری</label><input id="loyaltyAdminSearch" placeholder="نام، موبایل یا کد تخفیف..."></div><p class="muted">با هر ۵ سفارش معتبر پرداخت‌شده، یک کد ۱۰٪ اختصاصی به‌صورت خودکار صادر می‌شود. سفارش‌های شارژ کیف پول و اشتراک در شمارش خرید نیستند.</p><div class="table-wrap"><table class="admin-table"><thead><tr><th>مشتری</th><th>شماره حساب</th><th>خرید معتبر</th><th>مراحل ۵ خرید</th><th>کدهای اختصاصی</th><th>عملیات</th></tr></thead><tbody id="loyaltyAdminRows">${rows||'<tr><td colspan="6">هنوز مشتری‌ای برای استعلام وجود ندارد.</td></tr>'}</tbody></table></div></div><div class="panel-card"><h3>توضیح وضعیت پیام‌ها</h3><p>کد تخفیف در صندوق پیام‌های پروفایل و صندوق اعلان‌های مشتری ثبت می‌شود. وضعیت خوانده‌شده یا خوانده‌نشده برای هر مشتری جداگانه نگهداری می‌شود. این نسخه از ذخیره‌سازی مرورگر استفاده می‌کند؛ همگام‌سازی واقعی میان دستگاه‌ها به API سرور نیاز دارد.</p></div>`;
}

function simulatedCustomersAdminHtml(){const simSettings=(()=>{try{return JSON.parse(localStorage.getItem('novin_sim_bot_settings')||'{}')}catch{return {}}})();const events=(()=>{try{return JSON.parse(localStorage.getItem("novin_simulated_customer_events")||"[]")}catch{return []}})();const botData=(()=>{try{return JSON.parse(localStorage.getItem('novin_bot_data')||'{}')}catch{return {}}})();const botProfiles=Array.isArray(botData.botProfiles)?botData.botProfiles:[];const enabled=localStorage.getItem("novin_sim_customers_enabled")==="1";const journeys=new Set(events.map(x=>x.journeyId).filter(Boolean)).size;const buys=events.filter(x=>x.action==='پرداخت آزمایشی موفق').length;const mainJourneys=new Set(events.filter(x=>x.site==='main').map(x=>x.journeyId)).size;const gemJourneys=new Set(events.filter(x=>x.site==='gem').map(x=>x.journeyId)).size;return `<style>.sim-running-alert{padding:12px 14px;border:1px solid #16a34a;background:#dcfce7;color:#166534;border-radius:10px;margin-bottom:14px;font-weight:700}.sim-stopped-alert{padding:12px 14px;border:1px solid #9ca3af;background:#f3f4f6;color:#374151;border-radius:10px;margin-bottom:14px;font-weight:600}</style><div class="panel-card">${enabled?'<div class="sim-running-alert" role="status">🟢 ربات در حال کار است؛ چرخه‌ها به‌صورت آزمایشی اجرا می‌شوند.</div>':'<div class="sim-stopped-alert" role="status">⚪ ربات متوقف است.</div>'}<div class="panel-head"><div><h3>ربات آزمایشی هر دو فروشگاه</h3><p class="muted">در هر چرخه، برای هر دو سایت یک سفر جداگانه ثبت می‌شود: ورود/خروج، مشاهده و جست‌وجوی کالا، سبد، کد تخفیف، سفارش و پرداخت دمو، پروفایل و سفارش‌ها، کیف پول، پشتیبانی، نظر، اعلان‌ها و بررسی وضعیت سفارش.</p></div><span class="status ${enabled?'paid':'wait'}">${enabled?'فعال':'متوقف'}</span></div><div class="toolbar-left"><button type="button" class="primary" id="startSimCustomers">▶ شروع خودکار</button><button type="button" class="outline" id="stopSimCustomers">⏸ توقف ربات</button><button type="button" class="outline" id="runSimCustomerNow">⚡ اجرای چرخه همین الان</button><button type="button" class="outline" id="exportSimCustomerEvents">خروجی CSV گزارش‌ها</button><button type="button" class="danger-btn" id="clearSimCustomerEvents">پاک‌کردن گزارش شبیه‌سازی</button></div><div class="panel-card"><div class="panel-head"><div><h3>تنظیمات اجرای ربات</h3><p class="muted">فاصله اجرا و فروشگاه‌هایی را که ربات باید آزمایش کند انتخاب کن.</p></div></div><div class="form-grid"><div class="field"><label for="simBotInterval">فاصله اجرای خودکار</label><select id="simBotInterval"><option value="30" ${Number(simSettings.intervalSeconds||30)===30?'selected':''}>هر ۳۰ ثانیه</option><option value="60" ${Number(simSettings.intervalSeconds||30)===60?'selected':''}>هر ۱ دقیقه</option><option value="120" ${Number(simSettings.intervalSeconds||30)===120?'selected':''}>هر ۲ دقیقه</option><option value="300" ${Number(simSettings.intervalSeconds||30)===300?'selected':''}>هر ۵ دقیقه</option></select></div><div class="field"><label>فروشگاه‌های تحت آزمایش</label><div class="toolbar-left"><label><input type="checkbox" id="simBotMainEnabled" ${simSettings.mainEnabled!==false?'checked':''}> نوین‌شاپ</label><label><input type="checkbox" id="simBotGemEnabled" ${simSettings.gemEnabled!==false?'checked':''}> فروشگاه جم</label></div></div><div class="field full-field"><button type="button" class="primary" id="saveSimBotSettings">ذخیره تنظیمات ربات</button><small class="muted">با ذخیره تنظیمات، فاصله اجرای خودکار فوراً به‌روزرسانی می‌شود. برای شروع خودکار باید دکمه «شروع خودکار» را هم بزنید.</small></div></div></div><p class="muted"><b>حالت آزمایشی:</b> این ربات برای تست سناریوها گزارش ساختگی تولید می‌کند؛ وارد حساب واقعی نمی‌شود، کنترل‌های واقعی صفحه را کلیک نمی‌کند و سفارش/درآمد/موجودی/امتیاز واقعی را تغییر نمی‌دهد. پرداخت و نظرها ساختگی‌اند و نباید به‌عنوان فروش یا بازخورد واقعی نمایش داده شوند. زمان‌بندی تا وقتی صفحهٔ نوین‌شاپ باز و فعال باشد کار می‌کند.</p><div class="stats-grid"><div class="stat-card"><div class="stat-top">سفرهای ثبت‌شده</div><div class="stat-value">${digits(journeys)}</div></div><div class="stat-card"><div class="stat-top">سفرهای نوین‌شاپ</div><div class="stat-value">${digits(mainJourneys)}</div></div><div class="stat-card"><div class="stat-top">سفرهای سایت جم</div><div class="stat-value">${digits(gemJourneys)}</div></div><div class="stat-card"><div class="stat-top">پرداخت‌های دمو</div><div class="stat-value">${digits(buys)}</div></div><div class="stat-card"><div class="stat-top">مراحل ثبت‌شده</div><div class="stat-value">${digits(events.length)}</div></div><div class="stat-card"><div class="stat-top">آخرین فعالیت</div><div class="stat-value" style="font-size:16px">${events[0]?new Date(events[0].time).toLocaleTimeString('fa-IR'):'—'}</div></div></div><div class="panel-card"><div class="panel-head"><h3>پروفایل‌های ربات‌ها</h3><span class="muted">${digits(botProfiles.length)} پروفایل آزمایشی</span></div><p class="muted">این پروفایل‌ها ساختگی‌اند؛ احراز هویت واقعی انجام نشده و برای تست پنل نمایش داده می‌شوند.</p><div class="table-wrap"><table class="admin-table"><thead><tr><th>تصویر</th><th>مشتری</th><th>تماس آزمایشی</th><th>فروشگاه</th><th>امتیاز</th><th>کیف پول دمو</th><th>نوین پلاس</th><th>احراز هویت</th></tr></thead><tbody>${botProfiles.slice(0,100).map(p=>`<tr><td>${escapeHtml(p.avatar||'👤')}</td><td>${escapeHtml(p.name||'ربات مشتری')}</td><td>${escapeHtml(p.phone||'—')}</td><td>${p.site==='gem'?'فروشگاه جم':'نوین‌شاپ'}</td><td>${digits(p.points||0)}</td><td>${money(p.walletBalance||0)}</td><td>${p.plusSubscription?.active?'فعال (دمو)':'غیرفعال'}</td><td><span class="status ${(p.verificationStatus==='verified'||p.verified===true)?'paid':p.verificationStatus==='rejected'?'cancel':'wait'}">${escapeHtml(p.verificationStatus||'در انتظار بررسی (دمو)')}</span><div class="delivery-action-buttons"><button type="button" class="table-action" data-bot-verification="${escapeHtml(p.id||p.phone)}" data-bot-verification-action="verified">تأیید دمو</button><button type="button" class="danger-btn small" data-bot-verification="${escapeHtml(p.id||p.phone)}" data-bot-verification-action="rejected">رد</button><button type="button" class="outline small" data-bot-verification="${escapeHtml(p.id||p.phone)}" data-bot-verification-action="pending">بازنشانی</button></div></td></tr>`).join('')||'<tr><td colspan="8">هنوز پروفایلی ساخته نشده است.</td></tr>'}</tbody></table></div><p class="muted">پرونده‌های بیمه و نظرات ساختگی ربات‌ها نیز پس از همگام‌سازی در بخش‌های «بیمه مشتریان» و «نظرات مشتریان» دیده می‌شوند.</p></div><div class="panel-card"><div class="panel-head"><div><h3>عملیات ربات‌ها در جزئیات محصولات</h3><p class="muted">انتخاب رنگ، علاقه‌مندی، مقایسه، هشدار قیمت، گالری، سبد آزمایشی و پرسش محصول</p></div><span class="status wait">فقط آزمایشی</span></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>زمان</th><th>ربات</th><th>محصول</th><th>عملیات</th><th>جزئیات</th></tr></thead><tbody>${(Array.isArray(botData.productActions)?botData.productActions:[]).slice(0,100).map(a=>`<tr><td>${new Date(a.time||a.createdAt||Date.now()).toLocaleString('fa-IR')}</td><td>${escapeHtml(a.name||'ربات آزمایشی')}<small>${escapeHtml(a.phone||'')}</small></td><td>${escapeHtml(a.productName||a.productId||'—')}</td><td>${escapeHtml(a.action||'—')}</td><td>${escapeHtml(typeof a.detail==='string'?a.detail:JSON.stringify(a.detail||{}))}</td></tr>`).join('')||'<tr><td colspan="5">هنوز عملیات جزئیات محصول توسط ربات ثبت نشده است.</td></tr>'}</tbody></table></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>زمان</th><th>مشتری آزمایشی</th><th>فروشگاه</th><th>مرحله</th><th>جزئیات</th><th>مبلغ دمو</th></tr></thead><tbody>${events.slice(0,200).map(x=>`<tr><td>${new Date(x.time).toLocaleString('fa-IR')}</td><td>${escapeHtml(x.customer)}</td><td>${x.site==='gem'?'فروشگاه جم':'نوین‌شاپ'}</td><td><span class="status ${x.action==='پرداخت آزمایشی موفق'?'paid':'wait'}">${escapeHtml(x.action)}</span></td><td>${escapeHtml(x.detail||x.product||'—')}</td><td>${x.amount?money(x.amount):'—'}</td></tr>`).join('')||'<tr><td colspan="6">هنوز چرخه‌ای اجرا نشده است.</td></tr>'}</tbody></table></div></div>`}
function generateSimulatedCustomerJourney(site,cycleId){let product='محصول نمونه',amount=0;try{if(site==='gem'){const ps=JSON.parse(localStorage.getItem('novin_gem_products')||'[]').filter(p=>p.published!==false);if(ps.length){const p=ps[Math.floor(Math.random()*ps.length)];product=p.name||'بسته جم';amount=Number(p.price)||0;}}else if(Array.isArray(products)&&products.length){const ps=products.filter(p=>p.published!==false);const p=ps[Math.floor(Math.random()*ps.length)];if(p){product=p.name||'محصول فروشگاه';amount=Number(p.price)||0;}}}catch{}const names=['مریم آزمایشی','علی دمو','سارا شبیه‌سازی‌شده','محمد آزمایشی','آرمان دمو','نیلوفر آزمایشی','رضا شبیه‌سازی‌شده','هستی دمو'];const customer=names[Math.floor(Math.random()*names.length)]+' '+String(100+Math.floor(Math.random()*900));const journeyId='JRN-'+cycleId+'-'+(site==='gem'?'G':'N')+'-'+Math.random().toString(36).slice(2,5).toUpperCase();const now=Date.now();const store=site==='gem'?'فروشگاه جم':'نوین‌شاپ';const steps=[['ورود آزمایشی',`مشتری ساختگی وارد ${store} شد.`],['مرور صفحه اصلی',`صفحه اصلی ${store} و بخش‌های ویژه بررسی شد.`],['جست‌وجو و فیلتر',`جست‌وجو/دسته‌بندی محصولات برای «${product}» بررسی شد.`],['مشاهده جزئیات محصول',`جزئیات، قیمت و مشخصات «${product}» مشاهده شد.`],['افزودن به سبد آزمایشی',`«${product}» به سبد ساختگی افزوده شد.`],['بررسی سبد خرید','تعداد، مبلغ و گزینه‌های حذف/تغییر سبد بررسی شد.'],['بررسی کد تخفیف','بخش کد تخفیف و محاسبه تخفیف در حالت آزمایشی بررسی شد.'],['ثبت سفارش آزمایشی',`سفارش نمایشی ${journeyId} برای «${product}» آماده شد.`],['رفتن به درگاه دمو','صفحه پرداخت آزمایشی بررسی شد؛ هیچ اطلاعات بانکی واقعی وارد نشد.'],['پرداخت آزمایشی موفق',`رسید نمایشی DEMO-${String(now).slice(-8)} برای «${product}» تولید شد؛ پولی جابه‌جا نشد.`],['بررسی پروفایل','پروفایل، اطلاعات حساب، سابقه سفارش و پیام‌های آزمایشی بررسی شد.'],['بررسی کیف پول و امتیاز','نمایش کیف پول، امتیازها و امکانات باشگاه مشتریان بررسی شد؛ موجودی واقعی تغییر نکرد.'],['بررسی اعلان‌ها','اعلان‌ها و اطلاعیه‌های فروشگاه در حالت آزمایشی بررسی شد.'],['پیام به پشتیبانی',`پیام آزمایشی درباره سفارش ${journeyId} آماده شد؛ به پشتیبانی واقعی ارسال نشد.`],['ثبت نظر آزمایشی',`نظر ساختگی برای «${product}» با امتیاز ${3+Math.floor(Math.random()*3)} از ۵ ثبت‌شده در گزارش تست.`],['بررسی وضعیت سفارش','بخش پیگیری سفارش و وضعیت‌های تحویل در حالت آزمایشی بررسی شد.'],['خروج آزمایشی',`مشتری ساختگی از سناریوی ${store} خارج شد.`]];return steps.map((step,i)=>({id:journeyId+'-'+(i+1),journeyId,cycleId,time:now+i*250,customer,site,product,action:step[0],detail:step[1],amount:step[0]==='پرداخت آزمایشی موفق'?amount:0,simulated:true,paymentMode:'demo',sessionState:i===0?'entered':i===steps.length-1?'exited':'active'}));}
function generateSimulatedCustomerEvent(){return window.NovinBot.runCycle();}
function _legacyGenerateSimulatedCustomerEvent(){
 const cycleId=Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,5).toUpperCase();
 const events=[...generateSimulatedCustomerJourney('main',cycleId),...generateSimulatedCustomerJourney('gem',cycleId)];
 // Register clearly labelled demo orders in the same local order collection read by the admin panels.
 const journeys=[{site:'main',prefix:'SIM-NV',events:events.filter(e=>e.site==='main')},{site:'gem',prefix:'SIM-GEM',events:events.filter(e=>e.site==='gem')}];
 let createdOrders=0;
 for(const journey of journeys){
  const payment=journey.events.find(e=>e.action==='پرداخت آزمایشی موفق');
  if(!payment) continue;
  const amount=Math.max(0,Number(payment.amount)||0), name=journey.events[0]?.customer||'مشتری آزمایشی';
  const phone=journey.prefix+'-'+cycleId.replace(/[^A-Z0-9]/g,'').slice(-10);
  const orderNumber=journey.prefix+'-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,5).toUpperCase();
  const isGem=journey.site==='gem';
  const productName=journey.events.find(e=>e.action==='مشاهده جزئیات محصول')?.product||(isGem?'بسته جم آزمایشی':'محصول آزمایشی');
  const item={id:(isGem?'sim-gem-':'sim-main-')+cycleId,name:productName+(isGem?' (آزمایشی)':''),qty:1,quantity:1,price:amount};
  const order={id:orderNumber,number:orderNumber,type:isGem?'freefire_topup':'simulated_bot',game:isGem?'Free Fire':undefined,customer:{name,phone,email:'demo@example.invalid',address:'سفارش آزمایشی - ارسال واقعی ندارد',city:'آزمایشی',postal:'00000000'},items:[item],total:amount,amount,status:'paid',paymentGateway:'Demo Simulator',paymentReference:'DEMO-'+String(Date.now()).slice(-8),receipt:{number:'DEMO-REC-'+String(Date.now()).slice(-8),issuedAt:Date.now()},createdAt:Date.now(),updatedAt:Date.now(),simulated:true,simulationCycleId:cycleId,simulationSite:journey.site,note:'سفارش ساختگی تولیدشده توسط شبیه‌ساز؛ پرداخت و تحویل واقعی انجام نشده است.',playerId:isGem?'SIM-'+String(Math.floor(100000000+Math.random()*899999999)):''};
  orders.unshift(order); createdOrders++;
 }
 if(orders.length>3000) orders=orders.slice(0,3000);
 save();
 let list=[];try{list=JSON.parse(localStorage.getItem('novin_simulated_customer_events')||'[]')}catch{}
 list=[...events.reverse(),...list].slice(0,1500);
 localStorage.setItem('novin_simulated_customer_events',JSON.stringify(list));
 return {id:cycleId,journeys:2,steps:events.length,ordersCreated:createdOrders,action:'چرخه کامل هر دو فروشگاه'};
}
function stopSimulatedCustomerTimer(){window.NovinBot.stop();}
function refreshSimulatorPanelIfVisible(){if(['simCustomers','orders','freefire'].includes(currentAdminPanel))renderAdmin(currentAdminPanel);}
function startSimulatedCustomerTimer(){window.NovinBot.start();mergeBotData();refreshSimulatorPanelIfVisible();}
// ادغام داده‌های ربات (سفارش، مشتری، پیام، لاگ فعالیت) در حافظهٔ پنل مدیریت؛ idempotent است.
function mergeBotData(){try{const d=JSON.parse(localStorage.getItem('novin_bot_data')||'null');if(!d)return false;let ch=false;
 const oid=new Set(orders.map(o=>String(o.id)));for(const o of (d.orders||[]).slice().reverse()){if(!oid.has(String(o.id))&&Number(o.createdAt||0)>Number(localStorage.getItem('novin_bot_cleared_at')||0)){orders.unshift(o);oid.add(String(o.id));ch=true;}}
 if(orders.length>3000)orders=orders.slice(0,3000);
 const aid=new Set(activityLog.map(x=>String(x.id)));for(const x of (d.activity||[])){if(!aid.has(String(x.id))){activityLog.push(x);aid.add(String(x.id));ch=true;}}
 activityLog.sort((a,b)=>Number(a.time)-Number(b.time));if(activityLog.length>1500)activityLog=activityLog.slice(-1500);
 const cph=new Set(customers.map(c=>normalizePhone(c.phone)));for(const c of (d.customers||[])){const k=normalizePhone(c.phone);if(!cph.has(k)){customers.push(c);cph.add(k);ch=true;}}
 const mid=new Set(messages.map(m=>String(m.id)));for(const m of (d.messages||[])){if(!mid.has(String(m.id))){messages.push(m);mid.add(String(m.id));ch=true;}}
 const insIds=new Set(insuranceRecords.map(x=>String(x.id)));for(const r of (d.insuranceRecords||[])){if(!insIds.has(String(r.id))){insuranceRecords.unshift(r);insIds.add(String(r.id));ch=true;}}
 const revIds=new Set(reviews.map(x=>String(x.id)));for(const r of (d.reviews||[])){if(r.site==='gem')continue;if(!revIds.has(String(r.id))){reviews.unshift(r);revIds.add(String(r.id));ch=true;}}
 if(insuranceRecords.length>2000)insuranceRecords=insuranceRecords.slice(0,2000);
 if(reviews.length>3000)reviews=reviews.slice(-3000);
 if(ch)save();return ch;}catch(e){console.warn('Bot merge failed',e?.message||e);return false;}}
function onBotUpdated(){if(!mergeBotData())return;const av=$("#adminView");if(!av||av.classList.contains("hidden"))return;const ae=document.activeElement;if(ae&&ae.closest&&ae.closest("#adminContent")&&/^(INPUT|TEXTAREA|SELECT)$/.test(ae.tagName))return;if(['orders','freefire','activity','customers','messages','overview','simCustomers','delivery','reports','insurance','reviews','plus'].includes(currentAdminPanel))renderAdmin(currentAdminPanel);}
window.addEventListener('novin-bot-updated',onBotUpdated);window.addEventListener('storage',e=>{if(e.key==='novin_bot_data')onBotUpdated();});
mergeBotData();

function campaignsAdminHtml(){return `<div class="panel-card"><div class="panel-head"><div><h3>مرکز کمپین‌های فروش</h3><p class="muted">مدیریت پیشنهادها، کدهای تخفیف و بنرهای فروشگاه</p></div></div><div class="admin-feature-grid"><button class="admin-feature-tile" data-panel-link="deals"><b>％ شگفت‌انگیزها</b><span>انتخاب محصولات، عنوان و نمایش بخش ویژه</span></button><button class="admin-feature-tile" data-panel-link="discounts"><b>٪ کدهای تخفیف</b><span>ساخت، فعال‌سازی و حذف کدها</span></button><button class="admin-feature-tile" data-panel-link="announcements"><b>📢 اطلاعیه‌ها</b><span>اعلام فروش ویژه و خبرهای فروشگاه</span></button></div><div class="panel-head"><h3>وضعیت فعلی کمپین‌ها</h3></div><div class="customer-row"><div class="mini-info"><b>${escapeHtml(flashSale.title||'شگفت‌انگیزهای نوین‌شاپ')}</b><small>بخش فروش ویژه</small></div><span class="status ${flashSale.active?'paid':'wait'}">${flashSale.active?'فعال':'غیرفعال'}</span><button class="outline small" data-panel-link="deals">مدیریت</button></div><div class="customer-row"><div class="mini-info"><b>${digits(discounts.filter(d=>d.active).length)} کد تخفیف فعال</b><small>از ${digits(discounts.length)} کد ثبت‌شده</small></div><button class="outline small" data-panel-link="discounts">مدیریت کدها</button></div></div>`}
function verificationAdminHtml(){const pending=accounts.filter(a=>a.cardVerification?.status==='pending');let botData={};try{botData=JSON.parse(localStorage.getItem('novin_bot_data')||'{}')}catch{}const botProfiles=Array.isArray(botData.botProfiles)?botData.botProfiles:[];const botPending=botProfiles.filter(p=>!p.verified&&!['rejected','verified','verified (demo)'].includes(String(p.verificationStatus||'').toLowerCase()));const all=accounts.filter(a=>a.cardVerification);return `<div class="panel-card"><div class="panel-head"><div><h3>مدیریت احراز هویت‌ها</h3><p class="muted">درخواست‌های مشتریان و پروفایل‌های ربات آزمایشی در همین بخش دیده می‌شوند. تأیید ربات فقط وضعیت نمایشی را تغییر می‌دهد و احراز هویت واقعی نیست.</p></div><span class="status wait">${digits(pending.length+botPending.length)} در انتظار · شامل ربات‌ها</span></div><div class="verification-track-box"><h4>رهگیری درخواست احراز هویت مشتری</h4><p class="muted">کد رهگیری درج‌شده در پروفایل مشتری را وارد کن.</p><div class="admin-toolbar"><input id="verificationTrackInput" placeholder="مثلاً ID-..." dir="ltr"><button type="button" class="primary" id="verificationTrackBtn">رهگیری</button></div><div id="verificationTrackResult" aria-live="polite"></div></div><h3>درخواست‌های مشتریان</h3><div class="table-wrap"><table class="admin-table"><thead><tr><th>مشتری</th><th>موبایل</th><th>صاحب کارت</th><th>بانک</th><th>۴ رقم پایانی</th><th>کد رهگیری</th><th>وضعیت</th><th>زمان درخواست</th><th>عملیات</th></tr></thead><tbody>${all.map(a=>{const v=a.cardVerification;const pendingNow=v.status==='pending';return `<tr><td>${escapeHtml(a.name||'مشتری')}</td><td>${escapeHtml(a.phone||'')}</td><td>${escapeHtml(v.holder||'—')}</td><td>${escapeHtml(v.bank||'—')}</td><td dir="ltr">•••• ${escapeHtml(v.last4||'----')}</td><td dir="ltr">${escapeHtml(v.reference||'—')}</td><td><span class="status ${v.status==='verified'?'paid':v.status==='rejected'?'cancel':'wait'}">${v.status==='verified'?'تأییدشده (نمایشی)':v.status==='rejected'?'ردشده':'در انتظار بررسی'}</span></td><td>${v.requestedAt?new Date(v.requestedAt).toLocaleString('fa-IR'):'—'}</td><td>${pendingNow?`<button class="table-action" data-verify-account="${escapeHtml(a.phone)}" data-verification-action="verified">تأیید</button> <button class="danger-btn small" data-verify-account="${escapeHtml(a.phone)}" data-verification-action="rejected">رد درخواست</button>`:`<span class="muted">بررسی‌شده</span> <button class="outline small" data-verify-account="${escapeHtml(a.phone)}" data-verification-action="pending">بازگشایی</button>`}</td></tr>`}).join('')||'<tr><td colspan="9">درخواستی برای احراز هویت مشتری ثبت نشده است.</td></tr>'}</tbody></table></div><h3>احراز هویت ربات‌های آزمایشی (${digits(botProfiles.length)})</h3><p class="muted">این فهرست قبلاً در شبیه‌ساز بود؛ اکنون در پنل مدیریت احراز هویت نیز در دسترس است. نام، شماره و وضعیت ربات‌ها ساختگی‌اند.</p><div class="table-wrap"><table class="admin-table"><thead><tr><th>نام ربات</th><th>شماره آزمایشی</th><th>فروشگاه</th><th>وضعیت</th><th>آخرین بررسی</th><th>عملیات</th></tr></thead><tbody>${botProfiles.map(p=>{const st=String(p.verificationStatus||'pending (demo)').toLowerCase(),verified=p.verified===true||st==='verified'||st==='verified (demo)',rejected=st==='rejected';return `<tr><td>${escapeHtml(p.name||'ربات مشتری')}</td><td dir="ltr">${escapeHtml(p.phone||'—')}</td><td>${p.site==='gem'?'فروشگاه جم':'نوین‌شاپ'}</td><td><span class="status ${verified?'paid':rejected?'cancel':'wait'}">${verified?'تأییدشده (دمو)':rejected?'ردشده (دمو)':'در انتظار بررسی (دمو)'}</span></td><td>${p.verificationReviewedAt?new Date(p.verificationReviewedAt).toLocaleString('fa-IR'):'—'}</td><td>${!verified&&!rejected?`<button type="button" class="table-action" data-bot-verification="${escapeHtml(p.id||p.phone)}" data-bot-verification-action="verified">تأیید دمو</button> <button type="button" class="danger-btn small" data-bot-verification="${escapeHtml(p.id||p.phone)}" data-bot-verification-action="rejected">رد</button>`:`<button type="button" class="outline small" data-bot-verification="${escapeHtml(p.id||p.phone)}" data-bot-verification-action="pending">بازگشایی</button>`}</td></tr>`}).join('')||'<tr><td colspan="6">هنوز رباتی ساخته نشده است؛ از بخش شبیه‌ساز مشتری‌ها یک چرخه اجرا کن.</td></tr>'}</tbody></table></div></div>`}
