function openPayment(order){try{localStorage.setItem("novin_pending_demo_payment",JSON.stringify(order));const check=JSON.parse(localStorage.getItem("novin_pending_demo_payment")||"null");if(!check||String(check.number)!==String(order.number))throw new Error("Pending order verification failed");window.location.href="payment.html";}catch(err){console.error("Pending payment save failed:",err);toast("ذخیره سفارش برای پرداخت ناموفق بود؛ فضای ذخیره‌سازی مرورگر را بررسی کن.");}}
