  const paymentRef=(text.match(/DEMO-\d{6,}/i)||[])[0]?.toUpperCase();
  if(paymentRef){
    const knownOrders=orders.filter(o=>String(o.paymentReference||"").toUpperCase()===paymentRef);
    const knownWallet=walletTransactions.find(t=>String(t.paymentReference||"").toUpperCase()===paymentRef);
    if(paymentRef==="DEMO-2671678370") reply="شماره پیگیری DEMO-2671678370 در این فروشگاه یک تراکنش نمونه است و وضعیت نمایشی آن «موفق» ثبت شده است. این کد نمونه به بانک متصل نیست و نشان‌دهنده دریافت پول واقعی نیست.";
    else if(knownOrders.length){const o=knownOrders[knownOrders.length-1];reply=`وضعیت پرداخت آزمایشی سفارش #${o.number}: ${o.status==="paid"?"موفق":"در انتظار پرداخت یا تکمیل‌نشده"}. درگاه: ${o.paymentGateway||"درگاه آزمایشی"}. شماره پیگیری: ${paymentRef}. هیچ پول واقعی جابه‌جا نشده است.`;}
    else if(knownWallet)reply=`وضعیت شارژ کیف پول: ${knownWallet.status==="paid"?"موفق آزمایشی":"در انتظار بررسی"}. مبلغ: ${money(knownWallet.amount)}. شماره پیگیری: ${paymentRef}.`;
    else reply="این شماره پیگیری در تراکنش‌های ذخیره‌شده این مرورگر پیدا نشد. کد را بررسی کنید یا با مدیر فروشگاه صحبت کنید.";
  }
