  if(paymentRef){}
  else if(orderMatch){const o=orders.find(x=>String(x.number)===orderMatch[1]||String(x.id)===orderMatch[1]);if(o){const statusMap={pending:"در انتظار پرداخت",paid:"پرداخت‌شده",processing:"در حال آماده‌سازی",sent:"ارسال‌شده",delivered:"تحویل‌شده",cancel:"لغوشده"};reply=`وضعیت سفارش #${o.number}: ${statusMap[o.status]||o.status}. روش پرداخت: ${o.paymentGateway||({demo:"درگاه آزمایشی",wallet:"کیف پول",cod:"پرداخت هنگام تحویل"})[o.payment]||"ثبت نشده"}.`;if(o.deliveryDate)reply+=` تاریخ تحویل ثبت‌شده: ${o.deliveryDate}.`;if(o.deliverySlot)reply+=` بازه زمانی: ${o.deliverySlot}.`;if(o.shippingProvider)reply+=` شرکت ارسال: ${o.shippingProvider}.`;if(o.trackingCode)reply+=` کد رهگیری: ${o.trackingCode}.`;}else reply="سفارشی با این شماره پیدا نکردم. لطفاً شماره سفارش را بررسی کنید یا با مدیر صحبت کنید.";}
  else if(/سلام|درود|وقت بخیر/.test(text))reply="سلام و خوش آمدید 🌷 من دستیار نوین‌شاپ هستم. از گزینه‌های زیر می‌توانم کمک کنم: ۱) رهگیری سفارش با شماره سفارش ۲) پیگیری پرداخت با کد پیگیری ۳) راهنمای انتخاب و سازگاری محصول ۴) هزینه و زمان ارسال ۵) گارانتی و مرجوعی ۶) تخفیف‌ها. لطفاً موضوع یا شماره سفارش را بفرستید. اطلاعات کارت، رمز عبور یا کد ورود را در چت ارسال نکنید.";
  else if(/گارانتی|ضمانت|مرجوع|بازگشت/.test(text))reply="شرایط گارانتی و بازگشت در این نسخه نمونه است و باید با سیاست فروشگاه واقعی تکمیل شود. لطفاً شماره سفارش و نام محصول را بفرستید تا مدیر بتواند موضوع را بررسی کند؛ اطلاعات کارت بانکی را در چت ارسال نکنید.";
  else if(/پرداخت|درگاه|ملت|ملی|زرین|کیف پول/.test(text))reply="در صفحه پرداخت می‌توانید بین درگاه نمایشی بانک ملت، بانک ملی و زرین‌پال آزمایشی انتخاب کنید. این گزینه‌ها فقط ظاهر و جریان آزمایشی دارند و به بانک متصل نیستند؛ هیچ پولی دریافت نمی‌شود.";
  else if(/سلامت|رجیستر|رجیستری|نسخه|سازگار/.test(text))reply="برای گوشی‌ها، ظرفیت حافظه، رنگ، رجیستری و گارانتی دقیق باید با نسخه موجودی فروشگاه تأیید شود. نام کامل مدل را ارسال کنید تا مشخصات ثبت‌شده در کاتالوگ را پیدا کنم.";
