const heroSlides=[{eyebrow:"تجربه خرید هوشمند",title:"تکنولوژی،<br><em>نزدیک‌تر از همیشه.</em>",text:"محصولات دیجیتال منتخب، خرید ساده و پشتیبانی همراه شما.",tag:"✦ انتخاب ویژه",price:"از ۱۲,۹۰۰,۰۰۰ تومان"},{eyebrow:"پیشنهادهای تازه",title:"انتخاب بهتر،<br><em>خرید مطمئن‌تر.</em>",text:"موبایل و لوازم جانبی را با جزئیات و قیمت مشخص مقایسه کن.",tag:"✦ پیشنهادهای امروز",price:"محصولات منتخب"},{eyebrow:"برای دنیای دیجیتال",title:"لوازم کاربردی،<br><em>برای هر روز.</em>",text:"هدفون، شارژر و اکسسوری‌های کاربردی را در یک جا پیدا کن.",tag:"✦ همراه روزمره",price:"لوازم جانبی منتخب"}];let heroIndex=0;function setHeroSlide(index){heroIndex=(index+heroSlides.length)%heroSlides.length;const d=heroSlides[heroIndex],hero=document.querySelector(".hero");if(!hero)return;hero.querySelector(".hero-copy .eyebrow").textContent=d.eyebrow;hero.querySelector(".hero-copy h1").innerHTML=d.title;hero.querySelector(".hero-copy p").textContent=d.text;const tag=hero.querySelector(".float-tag"),price=document.querySelector("#heroFloatPrice");if(tag)tag.textContent=d.tag;if(price)price.textContent=d.price;document.querySelectorAll("[data-hero-slide]").forEach((b,i)=>{b.classList.toggle("active",i===heroIndex);b.setAttribute("aria-pressed",String(i===heroIndex));});hero.dataset.slide=String(heroIndex);}document.querySelector("#heroPrev")?.addEventListener("click",()=>setHeroSlide(heroIndex-1));document.querySelector("#heroNext")?.addEventListener("click",()=>setHeroSlide(heroIndex+1));document.querySelectorAll("[data-hero-slide]").forEach(b=>b.addEventListener("click",()=>setHeroSlide(Number(b.dataset.heroSlide))));let heroTimer=setInterval(()=>{if(!document.hidden)setHeroSlide(heroIndex+1)},6500);document.addEventListener("visibilitychange",()=>{if(document.hidden&&heroTimer){clearInterval(heroTimer);heroTimer=null;}else if(!document.hidden&&!heroTimer)heroTimer=setInterval(()=>setHeroSlide(heroIndex+1),6500);});
