function renderGemPlayerSearch(){const input=$('#gemPlayerSearch'),root=$('#gemPlayerSearchResults');if(!input||!root)return;const q=input.value.trim().toLowerCase();if(!q){root.innerHTML='<p class="muted">ابتدا Player ID، شماره سفارش یا شماره مشتری را وارد کن.</p>';return;}const list=orders.filter(o=>(o.type==='freefire_topup'||o.game==='Free Fire')&&[o.number,o.id,o.playerId,o.playerName,o.customer?.name,o.customer?.phone].some(v=>String(v||'').toLowerCase().includes(q)));root.innerHTML=list.length?`<table class="admin-table"><thead><tr><th>سفارش</th><th>مشتری</th><th>Player ID</th><th>بسته</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${list.map(o=>`<tr><td>#${escapeHtml(o.number||o.id)}</td><td>${escapeHtml(o.customer?.name||'—')}<small>${escapeHtml(o.customer?.phone||'')}</small></td><td dir="ltr">${escapeHtml(o.playerId||'—')}</td><td>${escapeHtml(o.items?.[0]?.name||'بسته جم')}</td><td>${statusLabel(o.status)}</td><td><button type="button" class="table-action" data-invoice="${o.id}">رسید</button> <button type="button" class="table-action" data-next-order-status="${o.id}">مرحله بعد</button></td></tr>`).join('')}</tbody></table>`:'<p class="muted">نتیجه‌ای پیدا نشد.</p>';}
function renderGemSupportNotes(){const root=$('#gemSupportNotesList');if(!root)return;let notes=[];try{notes=JSON.parse(localStorage.getItem('novin_gem_support_notes')||'[]')}catch{}root.innerHTML=notes.length?notes.slice().reverse().map(n=>`<div class="total-row"><span><b>سفارش #${escapeHtml(n.orderId)}</b><small style="display:block">${escapeHtml(n.note)} · ${new Date(n.createdAt).toLocaleString('fa-IR')}</small></span><button type="button" class="danger-btn small" data-gem-note-delete="${n.id}">حذف</button></div>`).join(''):'<p class="muted">هنوز یادداشت پشتیبانی ثبت نشده است.</p>';}
