// Free Fire rewards administration: local-browser demo controls.
function renderGemAdminPoints(){const root=document.querySelector('#gemAdminPointsTable');if(!root)return;let state={};try{state=JSON.parse(localStorage.getItem('novin_state_v2')||'{}')}catch{}const people=new Map();const ordersForGem=(Array.isArray(state.orders)?state.orders:[]).filter(o=>o.type==='freefire_topup'||o.game==='Free Fire');ordersForGem.forEach(o=>{const phone=String(o.customer?.phone||'').replace(/\s/g,'');if(phone&&!people.has(phone))people.set(phone,{phone,name:o.customer?.name||'مشتری جم'});});(Array.isArray(state.accounts)?state.accounts:[]).forEach(u=>{const phone=String(u.phone||'').replace(/\s/g,'');if(phone&&!people.has(phone))people.set(phone,{phone,name:u.name||'مشتری'});});const rows=[...people.values()].map(u=>{let d={points:0,claimed:[]};try{d=JSON.parse(localStorage.getItem('novin_gem_rewards_'+u.phone)||'{"points":0,"claimed":[]}')}catch{}return {...u,points:Number(d.points)||0,claimed:Array.isArray(d.claimed)?d.claimed.length:0}}).sort((a,b)=>b.points-a.points);root.innerHTML=rows.length?`<table class="admin-table"><thead><tr><th>مشتری</th><th>شماره تماس</th><th>امتیاز فعلی</th><th>درخواست جایزه</th><th>عملیات</th></tr></thead><tbody>${rows.map(u=>`<tr><td>${escapeHtml(u.name)}</td><td dir="ltr">${escapeHtml(u.phone)}</td><td><b>${digits(u.points)}</b></td><td>${digits(u.claimed)}</td><td><button type="button" class="table-action" data-gem-points-fill="${escapeHtml(u.phone)}">انتخاب مشتری</button></td></tr>`).join('')}</tbody></table>`:'<p class="muted">هنوز حسابی در داده‌های محلی پیدا نشد. شماره مشتری را می‌توانی در فرم بالا دستی وارد کنی.</p>';}
document.addEventListener('click',e=>{const pick=e.target.closest('[data-gem-points-fill]');if(pick){const form=document.querySelector('#gemAdminPointsForm');if(form){form.elements.phone.value=pick.dataset.gemPointsFill;const awardForm=document.querySelector('#gemAdminAwardForm');if(awardForm)awardForm.elements.phone.value=pick.dataset.gemPointsFill;form.elements.phone.focus();document.querySelector('#gemAdminPointsForm').scrollIntoView({behavior:'smooth',block:'center'});}return;}if(e.target.closest('#refreshGemPoints')){renderGemAdminPoints();return;}const tab=e.target.closest('[data-gem-admin-tab="rewards"]');if(tab){setTimeout(renderGemAdminPoints,0);}});
document.addEventListener('submit',e=>{const form=e.target.closest('#gemAdminAwardForm');if(!form)return;e.preventDefault();const fd=new FormData(form),phone=String(fd.get('phone')||'').replace(/\s/g,''),label=String(fd.get('label')||'').trim(),gems=Math.floor(Number(fd.get('gems'))),cost=Math.floor(Number(fd.get('cost'))),note=String(fd.get('note')||'').trim();if(!phone||!label||!Number.isFinite(gems)||gems<1||gems>1000000||!Number.isFinite(cost)||cost<0||cost>1000000){toast('اطلاعات بسته هدیه معتبر نیست.');return;}const key='novin_gem_rewards_'+phone;let d={points:0,claimed:[],earnedOrders:[],awardedBundles:[]};try{d=JSON.parse(localStorage.getItem(key)||'{"points":0,"claimed":[],"earnedOrders":[],"awardedBundles":[]}')}catch{}const points=Math.max(0,Number(d.points)||0);if(points<cost){const status=document.querySelector('#gemAdminAwardStatus');if(status)status.textContent=`امتیاز کافی نیست؛ مشتری ${points} امتیاز دارد و ${cost} امتیاز لازم است.`;toast('امتیاز مشتری برای این بسته کافی نیست.');return;}d.points=points-cost;d.awardedBundles=Array.isArray(d.awardedBundles)?d.awardedBundles:[];d.awardedBundles.push({id:'GIFT-'+Date.now(),label,gems,cost,note,status:'اعطا شده توسط مدیر',at:Date.now()});d.adminHistory=Array.isArray(d.adminHistory)?d.adminHistory:[];d.adminHistory.push({at:Date.now(),action:'award_bundle',label,gems,cost,before:points,after:d.points,note});localStorage.setItem(key,JSON.stringify(d));try{const state=JSON.parse(localStorage.getItem('novin_state_v2')||'{}');state.orders=Array.isArray(state.orders)?state.orders:[];const customer=(state.users||state.customers||[]).find(u=>String(u.phone||'').replace(/\\s/g,'')===phone)||{};const giftOrderId='GIFT-'+Date.now();state.orders.push({id:giftOrderId,number:giftOrderId,type:'gem_reward_gift',game:'Free Fire',customer:{name:customer.name||'مشتری جم',phone},phone,items:[{name:label,quantity:1,price:0,gems}],total:0,amount:0,status:'delivered',gift:true,rewardPointsCost:cost,createdAt:Date.now(),note:note||'هدیه ثبت‌شده توسط مدیر'});localStorage.setItem('novin_state_v2',JSON.stringify(state));}catch(err){console.warn('Gift order could not be added to shared state',err);}const status=document.querySelector('#gemAdminAwardStatus');if(status)status.textContent=`بسته «${label}» با مقدار ${gems} جم برای ${phone} ثبت شد؛ ${cost} امتیاز کسر شد و ${d.points} امتیاز باقی ماند. هدیه به سفارش‌های مشتری هم اضافه شد.`;renderGemAdminPoints();toast('بسته هدیه در پروفایل و فهرست سفارش‌های جم ثبت شد.');});
document.addEventListener('submit',e=>{const form=e.target.closest('#gemAdminPointsForm');if(!form)return;e.preventDefault();const fd=new FormData(form),phone=String(fd.get('phone')||'').replace(/\s/g,''),action=String(fd.get('action')||'add'),amount=Math.floor(Number(fd.get('points'))),note=String(fd.get('note')||'').trim();if(!phone||!Number.isFinite(amount)||amount<0||amount>1000000){toast('شماره تماس یا مقدار امتیاز معتبر نیست.');return;}const key='novin_gem_rewards_'+phone;let d={points:0,claimed:[],earnedOrders:[]};try{d=JSON.parse(localStorage.getItem(key)||'{"points":0,"claimed":[],"earnedOrders":[]}')}catch{}const before=Math.max(0,Number(d.points)||0);d.points=action==='set'?amount:action==='subtract'?Math.max(0,before-amount):Math.min(1000000,before+amount);d.adminHistory=Array.isArray(d.adminHistory)?d.adminHistory:[];d.adminHistory.push({at:Date.now(),action,amount,before,after:d.points,note});localStorage.setItem(key,JSON.stringify(d));const status=document.querySelector('#gemAdminPointsStatus');if(status)status.textContent=`امتیاز مشتری ${phone} از ${before} به ${d.points} تغییر کرد. ${note?'یادداشت: '+note:''}`;renderGemAdminPoints();toast('امتیاز جم ذخیره شد.');});


/* Product gallery UX: 5-second card slideshow + click-to-zoom lightbox. */
(()=>{
 const parseImages=(raw)=>{try{const a=JSON.parse(raw||'[]');return Array.isArray(a)?a.filter(x=>typeof x==='string'&&/^https?:\/\//i.test(x)):[]}catch{return []}};
 let zoomImages=[],zoomIndex=0;
 function ensureZoom(){let box=document.getElementById('productImageZoom');if(box)return box;box=document.createElement('div');box.id='productImageZoom';box.className='product-image-zoom';box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');box.setAttribute('aria-label','نمایش بزرگ تصویر');box.innerHTML='<button type="button" class="zoom-close" aria-label="بستن">×</button><button type="button" class="zoom-prev" aria-label="تصویر قبلی">‹</button><img alt="تصویر بزرگ محصول"><button type="button" class="zoom-next" aria-label="تصویر بعدی">›</button><div class="zoom-counter"></div>';document.body.appendChild(box);box.addEventListener('click',e=>{if(e.target===box||e.target.closest('.zoom-close'))closeZoom();else if(e.target.closest('.zoom-prev'))showZoom(zoomIndex-1);else if(e.target.closest('.zoom-next'))showZoom(zoomIndex+1)});return box}
 function showZoom(i){if(!zoomImages.length)return;zoomIndex=(i+zoomImages.length)%zoomImages.length;const box=ensureZoom(),img=box.querySelector('img');img.src=zoomImages[zoomIndex];box.querySelector('.zoom-counter').textContent=`${zoomIndex+1} / ${zoomImages.length}`;box.classList.add('is-open');document.body.classList.add('image-zoom-open')}
 function closeZoom(){const box=document.getElementById('productImageZoom');if(box)box.classList.remove('is-open');document.body.classList.remove('image-zoom-open')}
 function openZoom(images,current){zoomImages=images.filter(Boolean);const found=zoomImages.indexOf(current);showZoom(found<0?0:found)}
 document.addEventListener('click',e=>{
  const cardVisual=e.target.closest('.product-visual');
  if(cardVisual&&e.target.closest('.product-card-slideshow')){const imgs=parseImages(cardVisual.dataset.cardImages);if(imgs.length)openZoom(imgs,e.target.closest('img').src);return}
  const zoomBtn=e.target.closest('[data-image-zoom]');
  const detailImg=e.target.closest('.detail-main-image img');
  if(zoomBtn||detailImg){const src=document.getElementById('detailMainImage')?.src;if(src){const imgs=[...document.querySelectorAll('.detail-thumb[data-detail-image]')].map(b=>b.dataset.detailImage);if(!imgs.includes(src))imgs.unshift(src);openZoom([...new Set(imgs)],src)}return}
 });
 document.addEventListener('keydown',e=>{if(e.key==='Escape')closeZoom();if(!document.getElementById('productImageZoom')?.classList.contains('is-open'))return;if(e.key==='ArrowLeft')showZoom(zoomIndex+1);if(e.key==='ArrowRight')showZoom(zoomIndex-1)});
 // One shared timer avoids creating/leaking an interval for every product card.
 window.setInterval(()=>{
  if(document.hidden)return;
  document.querySelectorAll('.product-card .product-visual[data-card-images]').forEach(visual=>{
   const imgs=parseImages(visual.dataset.cardImages);if(imgs.length<2)return;
   const img=visual.querySelector('.product-card-slideshow');if(!img)return;
   let index=Number(img.dataset.slideIndex||0);index=(index+1)%imgs.length;
   const candidate=imgs[index];
   const probe=new Image();probe.onload=()=>{img.src=candidate;img.dataset.slideIndex=String(index);};probe.onerror=()=>{img.dataset.slideIndex=String(index);};probe.src=candidate;
  });
 },5000);
})();
